(function(){const t=document.createElement("link").relList;if(t&&t.supports&&t.supports("modulepreload"))return;for(const n of document.querySelectorAll('link[rel="modulepreload"]'))a(n);new MutationObserver(n=>{for(const s of n)if(s.type==="childList")for(const i of s.addedNodes)i.tagName==="LINK"&&i.rel==="modulepreload"&&a(i)}).observe(document,{childList:!0,subtree:!0});function o(n){const s={};return n.integrity&&(s.integrity=n.integrity),n.referrerPolicy&&(s.referrerPolicy=n.referrerPolicy),n.crossOrigin==="use-credentials"?s.credentials="include":n.crossOrigin==="anonymous"?s.credentials="omit":s.credentials="same-origin",s}function a(n){if(n.ep)return;n.ep=!0;const s=o(n);fetch(n.href,s)}})();const yt=[{id:"a1_meet",type:"event",title:"1막 · 하얀 진료실",bg:"art/a1_meet.webp",art:"[S2-1] 막 들어온 여자와 마주한 닥터",noMirror:!0,lines:["하얀 벽, 하얀 바닥, 하얀 문고리. 신경질적일 정도로 하얗게 꾸며진 방.","시선이 닿지 않는 천장에서만, 진득한 콧물 같은 것이 뚝, 뚝 떨어진다.",{who:"닥터",text:"어서 와. 어서."},"닥터는 웃고 있다. 자연스럽다기보다는, 웃기로 마음먹은 사람의 얼굴이다.",{who:"닥터",text:"…그 얼굴. 선반에서 본 것 같은데.",if:{ending:"collection"}},{text:"여자는 아직 선글라스를 벗지 않았다.",if:{flag:{face_hidden:!0}}},"젖은 모자 끝에서 검은 빗물이 떨어진다."],choices:[{text:"젖은 모자를 책상 위 서류 더미에 툭 던진다",effects:[{set:{hat_place:"desk"}},{add:{desire:1,trust:-1}}],goto:"a1_hat"},{text:"모자를 벗어 손에 든다",effects:[{set:{hat_place:"hand"}}],reply:"여자는 모자를 손끝에 걸친다. 빗물이 손목을 타고 흐른다.",goto:"a1_papers"},{text:"닥터에게 모자를 건넨다",effects:[{set:{hat_place:"doctor"}},{add:{trust:1}}],reply:{who:"닥터",text:"…친절하네. 요즘 그런 건 돈이 안 되는데."},goto:"a1_papers"}]},{id:"a1_hat",type:"event",title:"1막 · 하얀 진료실",bg:"art/a1_hat.webp",art:"[S2-2] 모자를 던지는 여자, 찡그리는 닥터",noMirror:!0,lines:["서류에 빗물이 번진다. 닥터가 예민하게 얼굴을 찡그린다.","멈칫. 닥터가 가던 길을 멈추고 젖은 모자를 집어 든다.",{who:"닥터",text:"이… 이걸 왜 여기다 처박아. 아무 데나."},"닥터는 중얼거리며 모자를 구석에 내던진다."],choices:[{text:"…",goto:"a1_papers"}]},{id:"a1_papers",type:"event",title:"1막 · 하얀 진료실",bg:"art/a1_papers.webp",art:"[S2-4] 종이 더미를 뒤척이는 닥터",noMirror:!0,lines:["비가 와서인지 콤콤한 곰팡이 냄새가 지하에 고여 있다.","닥터는 탑처럼 쌓인 종이 더미에 머리를 박고 무언가를 찾기 시작한다. 기호와 해부도가 그려진 종이가 휙휙 날아다닌다.",{who:"닥터",text:"잠깐, 잠깐. 어디 뒀더라… 아무것도 만지지 마. 아무것도."},"여자는 코를 막고, 느린 보폭으로 방을 둘러본다."],choices:[{text:"진료실을 둘러본다",goto:"a1_north"}],onEnter:[{set:{stage:1}}]},{id:"a1_north",type:"room",title:"1막 · 대기실 · 책상 쪽",bg:"art/a1_north.webp",art:"[배경] 책상, 면허증 액자, 축음기",intro:"책상 쪽. 면허증 액자와 축음기, 종이가 어지러운 책상.",idle:"책상 쪽이다. 살펴볼 곳을 누르세요.",hotspots:[{id:"license",label:"면허증 액자",rect:[16,28,32,24],goto:"a1_lic"},{id:"gramophone",label:"축음기",rect:[2,46,22,24],text:["낡은 축음기. 바늘이 올라가 있다.","음반 라벨에는 「달빛」. 그 옆에 연필로 ‘4분 10초’라고 적혀 있다.","여자는 별생각 없이 그 숫자를 적어 둔다.","메모지 뒷면에, 거꾸로 쓴 무언가가 배어 나와 있다."],textAgain:"음반 「달빛」. 4분 10초.",effects:[{give:"item_record_memo"}],sprite:"obj/gramophone.png",mirror:["거울 속에서 메모 뒷면의 글씨가 바로 선다.","‘31’","그 아래 작게. ‘매일 보는 날.’"],mirrorEffects:[{clue:"hint_memo_back"}]},{id:"eyes",label:"유리 눈알 받침",rect:[58,60,24,14],text:["받침대에 꽂힌 유리 눈알들. 저마다 색과 광택이 다르다.","받침마다 작은 이름표와 날짜가 붙어 있다. ‘L. 1941.11’ ‘M. 1942.03’…","마지막 받침의 이름표는 비어 있다.","돋보기가 있다면 홍채 무늬까지 볼 수 있을 텐데."],textAgain:"마지막 이름표는 비어 있다. 맨눈으로는 홍채 무늬가 보이지 않는다.",effects:[{clue:"clue_shelf"},{add:{suspicion:1}}],use:{item_magnifier:{text:"돋보기를 받침 위로 가져간다.",goto:"a1_spec1"}},useHint:"작은 글씨, 작은 무늬. 확대해 볼 무언가가 필요하다.",sprite:"obj/eyes_stand.png"},{id:"news",label:"구겨진 신문",rect:[56,78,26,18],goto:"a1_news"},{id:"drawer",label:"잠긴 서랍",rect:[84,78,14,18],if:{not:{has:"item_magnifier"}},goto:"a1_drawer",sprite:"obj/drawer.png"},{id:"drawer_open",label:"열린 서랍",rect:[84,78,14,18],if:{has:"item_magnifier"},text:"서명된 동의서 묶음. 맨 위 서명은 ‘L.’",sprite:"obj/drawer.png"},{id:"eye",label:"반짝이는 것",rect:[4,40,10,10],hidden:!0,once:!0,text:"축음기 나팔 안쪽에 무언가 굴러 들어가 있다.",eye:"eye_horn"},{id:"curtain",label:"칸막이 커튼",rect:[34,6,30,62],if:{not:{any:[{flag:{curtain_open:!0}},{flag:{curtain_unlocked:!0}}]}},goto:"a1_curtain"},{id:"curtain_unlocked",label:"칸막이 커튼",rect:[34,6,30,62],if:{all:[{flag:{curtain_unlocked:!0}},{not:{flag:{curtain_open:!0}}}]},goto:"a1_curtain_open"},{id:"curtain_pass",label:"걷힌 커튼",rect:[34,6,30,62],if:{flag:{curtain_open:!0}},sfx:"rail",goto:"a1_west"}],mirror:{text:"거울에 비친 책상. 종이 더미 사이에서 눈알 받침들이 이쪽을 보는 것 같다."},triggers:[{id:"peek",if:{all:[{all:[{not:{flag:{peeked:!0}}},{gte:{gaze:100}}]},{not:{flag:{stage:3}}}]},goto:"a1_peek"},{id:"back3",if:{all:[{flag:{stage:3}},{gte:{gaze:100}}]},goto:"a1_return_early"},{id:"warn12",if:{all:[{not:{flag:{peeked:!0}}},{not:{flag:{stage:3}}},{gte:{gaze:70}},{lte:{gaze:99}},{not:{flag:{gaze_warned:!0}}}]},effects:[{set:{gaze_warned:!0}}],lines:["종이 넘기는 소리가 멎는다. …다시 넘어간다."]},{id:"warn3",if:{all:[{flag:{stage:3}},{gte:{gaze:70}},{lte:{gaze:99}},{not:{flag:{gaze_warned3:!0}}}]},effects:[{set:{gaze_warned3:!0}}],lines:["뒷방 문고리가 반쯤 돌다, 멈춘다."]}],choices:[{text:"닥터를 기다린다",if:{flag:{stage:3}},goto:"a1_return"},{text:"선반 쪽 →",kind:"ghost",goto:"a1_east",dir:"right"}],gaze:{look:6,mirror:10,if:{any:[{not:{flag:{peeked:!0}}},{flag:{stage:3}}]},mirror1:5},ambient:["똑.","축음기 바늘이 한 칸 넘어간다.","종이 넘기는 소리가 멎는다.","…","등 뒤에서 곰방대 냄새."],viewClass:{"lamp-off":{flag:{stage:3}}}},{id:"a1_spec1",type:"event",title:"1막 · 눈알 견본",bg:"art/a1_drawer.webp",art:"[확대] 이름표 붙은 유리 눈알 받침",noMirror:!0,onFirst:[{clue:"clue_shelf"}],lines:["돋보기를 대고, 받침대의 유리 눈을 하나씩 들여다본다.","첫 번째 눈. 푸른 홍채. 무대 조명을 받은 듯한 반짝임. 뒷면에 가는 금 다섯 줄이 그어져 있다. 오선지처럼.","이 눈의 이름표는?"],choices:[{text:"‘L. 1941.11’",effects:[{set:{spec1:!0}}],goto:"a1_spec2"},{text:"‘M. 1942.03’",effects:[{set:{spec1:!1}}],goto:"a1_spec2"},{text:"비어 있는 이름표",effects:[{set:{spec1:!1}}],goto:"a1_spec2"}]},{id:"a1_spec2",type:"event",title:"1막 · 눈알 견본",bg:"art/a1_drawer.webp",art:"[확대] 이름표 붙은 유리 눈알 받침",noMirror:!0,lines:["두 번째 눈. 잿빛 홍채. 가장자리에 탄가루 같은 검은 점이 박혀 있다.","이 눈의 이름표는?"],choices:[{text:"‘L. 1941.11’",effects:[{set:{spec2:!1}}],goto:"a1_spec3"},{text:"‘M. 1942.03’",effects:[{set:{spec2:!0}}],goto:"a1_spec3"},{text:"비어 있는 이름표",effects:[{set:{spec2:!1}}],goto:"a1_spec3"}]},{id:"a1_spec3",type:"event",title:"1막 · 눈알 견본",bg:"art/a1_drawer.webp",art:"[확대] 이름표 붙은 유리 눈알 받침",noMirror:!0,lines:["세 번째 눈. 금귤빛 홍채. 흠집 하나 없이, 새것처럼 반짝인다.","이 눈의 이름표는?"],choices:[{text:"‘L. 1941.11’",effects:[{set:{spec3:!1}}],goto:"a1_spec_end"},{text:"‘M. 1942.03’",effects:[{set:{spec3:!1}}],goto:"a1_spec_end"},{text:"비어 있는 이름표",effects:[{set:{spec3:!0}}],goto:"a1_spec_end"}]},{id:"a1_spec_end",type:"event",title:"1막 · 눈알 견본",bg:"art/a1_drawer.webp",art:"[확대] 유리 눈알 받침",noMirror:!0,onEnter:[{clue:"clue_specimen",if:{flag:{spec1:!0,spec2:!0,spec3:!0}}},{add:{suspicion:1},if:{all:[{flag:{spec1:!0,spec2:!0,spec3:!0}},{not:{flag:{spec_solved:!0}}}]}},{set:{spec_solved:!0},if:{flag:{spec1:!0,spec2:!0,spec3:!0}}}],lines:[{text:"오선지. 탄가루. 그리고 아무것도 묻지 않은 것 하나.",if:{flag:{spec1:!0,spec2:!0,spec3:!0}}},{text:"빈 이름표 옆, 잉크병 뚜껑이 열려 있다.",if:{flag:{spec1:!0,spec2:!0,spec3:!0}}},{who:"여자",text:"견본치고는 손때가 많이 탔네.",if:{flag:{spec1:!0,spec2:!0,spec3:!0}}},{text:"이름표와 짝이 잘 맞지 않는다. 무언가 놓치고 있다. 신문을 다시 볼까.",if:{not:{flag:{spec1:!0,spec2:!0,spec3:!0}}}}],choices:[{text:"돌아간다",kind:"ghost",goto:"a1_north"}]},{id:"a1_ratbox",type:"event",title:"1막 · 쥐 상자",bg:"art/a1_rats.webp",art:"[S2-10] 연구용 쥐 상자",noMirror:!0,lines:["닥터가 없는 사이, 여자는 쥐 상자 앞에 쪼그려 앉는다.","쥐들이 전부 이쪽을 본다. 반짝인다. …전부?","진짜라면, 깜빡일 것이다."],choices:[{text:"가만히 지켜본다",goto:"a1_ratwatch"},{text:"그만 본다",kind:"ghost",goto:"a1_south"}]},{id:"a1_ratwatch",type:"puzzle",kind:"watch",title:"1막 · 쥐 상자",bg:"art/a1_rats.webp",art:"[S2-10] 연구용 쥐 상자",noMirror:!0,count:5,real:2,maxFails:3,hint:"rat",spots:[[14,62],[32,50],[50,64],[68,52],[86,63]],prompt:"어둠 속에 반짝이는 것이 다섯 쌍. 하나만 살아 있다. 고른다.",wrong:"…깜빡이지 않는다. 유리다.",success:"a1_rat_real",fail:"a1_south",failText:["쥐들이 일제히 이쪽을 본다. 하나도 깜빡이지 않는다.","등 뒤에서 발소리. 여자는 덮개를 내린다."],failEffects:[{set:{rat_lost:!0}}],exit:"a1_south",blinkMs:120,blinkGap:[5e3,8e3],shuffle:{count:2,ms:900}},{id:"a1_rat_real",type:"event",title:"1막 · 쥐 상자",bg:"art/a1_rats.webp",art:"[S2-10] 연구용 쥐 상자",noMirror:!0,lines:["구석의 쥐가 여자를 올려다본다.",{who:"여자",text:"…너도 여기 오래 있었구나."},"쥐가 코를 킁킁댄다. 손수건 쪽이다."],choices:[{text:"그냥 둔다",kind:"ghost",goto:"a1_south"}],use:{item_maggot:{effects:[{take:"item_maggot"},{give:"item_backkey"},{set:{rat_friend:!0}}],text:["쥐가 구더기를 낚아채더니, 상자 틈으로 빠져나간다.","뒷방 문 아래로 사라졌다가… 무언가를 물고 돌아온다.","녹슨 열쇠. 여자는 재빨리 장갑 속에 밀어 넣는다.",{who:"여자",text:"뇌물은 쥐한테도 통하는군."}],goto:"a1_south"},item_coins:{text:"쥐는 금화에 관심이 없다. 현명하다."},item_mirror:{text:"거울 속 자기 모습에, 쥐가 털을 곤두세운다."}},useWrong:"쥐는 그런 걸 먹지 않는다."},{id:"a1_lic",type:"event",title:"1막 · 면허증",bg:"art/a1_license.webp",art:"[확대] 이름이 긁힌 면허증 액자",onFirst:[{clue:"clue_license"},{clue:"hint_lic_no"}],lines:["빛바랜 의사 면허증. 이름 부분이 칼로 긁혀 지워져 있다.","그 위에 붉은 도장. ‘면허 취소 — 비윤리적 불법 시술 및 연구’.",`발급 번호도 끝이 긁혀 있다.

No. 1928-07▒▒`],mirror:{text:"거울에 비춰도 이름은 읽을 수 없다. 긁힌 자국이 너무 깊다."},choices:[{text:"돌아간다",kind:"ghost",goto:"a1_north"}]},{id:"a1_news",type:"event",title:"1막 · 신문",bg:"art/a1_news.webp",art:"[확대] 낙서된 신문",onFirst:[{clue:"clue_newspaper"}],lines:["책상 위 구겨진 신문. 1면은 전황 기사로 빽빽하다.","구석의 작은 기사. ‘가수 L, 공연 직후 실종. 마지막 목격 장소는 빈민가 골목.’","그녀의 푸른 눈은 유명했다고 적혀 있다.","그 아래 더 작은 기사. ‘광부 M., 폐갱도 수색 중 실종.’","기사 사진 속 인물에는 누군가 안경과 콧수염을 낙서해 놓았다."],choices:[{text:"돌아간다",kind:"ghost",goto:"a1_north"}]},{id:"a1_drawer",type:"puzzle",kind:"code",title:"1막 · 서랍",bg:"art/a1_drawer.webp",art:"[확대] 책상 서랍",noMirror:!0,answer:"0731",prompt:"네 자리 숫자 자물쇠가 달린 서랍. 닥터가 매일 보는 숫자일 것이다.",wrong:"꿈쩍도 하지 않는다.",success:"a1_drawer_open",choices:[],hint:"drawer",exit:"a1_north"},{id:"a1_drawer_open",type:"event",title:"1막 · 서랍",bg:"art/a1_drawer.webp",art:"[확대] 열린 서랍",onFirst:[{give:"item_magnifier"},{add:{suspicion:1}}],lines:[{text:"딸깍. 서랍이 열린다.",fx:"thud"},"안에는 돋보기 하나. 그리고 같은 서식의 동의서 묶음.","모두 서명이 되어 있다. 맨 위 장의 서명은… ‘L.’","여자는 돋보기만 챙기고 서랍을 조용히 닫는다."],choices:[{text:"돌아간다",kind:"ghost",goto:"a1_north"}]},{id:"a1_east",type:"room",title:"1막 · 대기실 · 선반 쪽",bg:"art/a1_east.webp",art:"[배경] 해부체 유리병 선반, 실험대",intro:"선반 쪽. 해부체가 담긴 유리병들이 벽을 가득 채우고 있다.",idle:"선반 쪽이다. 살펴볼 곳을 누르세요.",hotspots:[{id:"books",label:"꽂힌 책들",rect:[66,2,32,13],if:{not:{flag:{books_done:!0}}},text:[{text:"벽 메모가 떠오른다. ‘책은 키 작은 것부터.’",if:{clue:"hint_book_rule"}}],goto:"a1_books"},{id:"books_done",label:"꽂힌 책들",rect:[66,2,32,13],if:{flag:{books_done:!0}},goto:"a1_books"},{id:"jars",label:"해부체 유리병",rect:[4,16,62,28],text:["각종 생물의 해부체가 담긴 유리병들.","몇몇은 아직 꿈틀거리는 것 같다. 기분 탓이다. 아마도."]},{id:"beaker",label:"비커",rect:[8,46,44,18],goto:"a1_beaker"},{id:"hat",label:"중절모",rect:[60,64,22,12],text:["실험대 위에 놓인 남자 중절모.","안쪽 띠에 수놓인 이니셜. ‘M. D.’","Mole Doctor. 두더지 의사."]},{id:"notes",label:"벽 메모",rect:[82,32,16,22],text:["벽에 덕지덕지 붙은 공식과 기호들.","구석에 짧은 메모 하나. ‘책은 키 작은 것부터. 그래야 읽힌다.’","한 장에만 알아볼 수 있는 글씨가 있다.","‘벌레비 — 하늘에서 온 것. 재생 속도 40배. 인간 적용: 미확인.’","나머지는 전부 좌우가 뒤집힌 글씨다."],textAgain:["‘인간 적용: 미확인.’","구석의 메모. ‘책은 키 작은 것부터. 그래야 읽힌다.’"],effects:[{add:{suspicion:1}},{clue:"hint_book_rule"}],mirror:["거울 속에서, 뒤집힌 글씨가 바로 선다.","‘1호 이후. 빛을 막을 것.’","‘빛을 보면 굳는다. 굳으면 깨어난다.’"],mirrorEffects:[{clue:"hint_mirror_memo"}]},{id:"bucket",label:"양동이",rect:[46,86,14,12],text:["천장에서 떨어진 검은 물이 양동이에 고여 있다. 수면 위로 하얀 것들이 떠 있다. 구더기다.","여자는 얼굴을 찌푸리면서도, 한 마리를 손수건에 싸서 챙긴다. 쓸모가 있을지도 모른다."],textAgain:"구더기가 떠 있는 양동이.",effects:[{give:"item_maggot"}],sprite:"obj/bucket.png"},{id:"eye",label:"반짝이는 것",rect:[88,88,10,10],hidden:!0,once:!0,text:"타일 틈에 동그란 것이 끼어 있다.",eye:"eye_floor"},{id:"irondoor",label:"철문",rect:[20,28,18,40],text:["들어온 문. 안에서 보니 더 두껍다."]}],mirror:{text:"거울에 비친 유리병들. 병마다 여자의 얼굴이 오목하게, 볼록하게 일그러진다."},triggers:[{id:"peek",if:{all:[{all:[{not:{flag:{peeked:!0}}},{gte:{gaze:100}}]},{not:{flag:{stage:3}}}]},goto:"a1_peek"},{id:"back3",if:{all:[{flag:{stage:3}},{gte:{gaze:100}}]},goto:"a1_return_early"},{id:"warn12",if:{all:[{not:{flag:{peeked:!0}}},{not:{flag:{stage:3}}},{gte:{gaze:70}},{lte:{gaze:99}},{not:{flag:{gaze_warned:!0}}}]},effects:[{set:{gaze_warned:!0}}],lines:["종이 넘기는 소리가 멎는다. …다시 넘어간다."]},{id:"warn3",if:{all:[{flag:{stage:3}},{gte:{gaze:70}},{lte:{gaze:99}},{not:{flag:{gaze_warned3:!0}}}]},effects:[{set:{gaze_warned3:!0}}],lines:["뒷방 문고리가 반쯤 돌다, 멈춘다."]}],choices:[{text:"닥터를 기다린다",if:{flag:{stage:3}},goto:"a1_return"},{text:"← 책상 쪽",kind:"ghost",goto:"a1_north",dir:"left"}],gaze:{look:6,mirror:10,if:{any:[{not:{flag:{peeked:!0}}},{flag:{stage:3}}]},mirror1:5},ambient:["병 속에서 무언가 몸을 뒤척인다.","똑. 똑.","…","양동이 수면이 저 혼자 흔들린다."],viewClass:{"lamp-off":{flag:{stage:3}}}},{id:"a1_books",type:"puzzle",kind:"sort",title:"1막 · 선반의 책",bg:"art/a1_east.webp",art:"[배경] 선반",books:[70,52,84,60,76],code:"5208",hint:"books",swapsPerFail:6,prompt:"책 두 권을 차례로 눌러 자리를 바꾼다.",successEffects:[{set:{books_done:!0}},{clue:"hint_books"}],exit:"a1_east",mirrorToggle:!0,gaze:{look:6,mirror:10,if:{any:[{not:{flag:{peeked:!0}}},{flag:{stage:3}}]},mirror1:5}},{id:"a1_curtain",type:"puzzle",kind:"code",title:"1막 · 칸막이 커튼",bg:"art/a1_south.webp",art:"[배경] 칸막이 커튼",answer:"8052",hint:"curtain",prompt:`진료실 안쪽을 가린 칸막이 커튼. 고리를 묶은 네 자리 숫자 자물쇠.
고리는 쇠붙이다. 떨어지면 소리가 날 것이다.`,wrong:"꿈쩍도 하지 않는다.",successEffects:[{set:{curtain_unlocked:!0}}],success:"a1_curtain_unlock",choices:[],exit:"a1_north",mirrorToggle:!0,mirrorGlintIf:{flag:{curtain_failed:!0}},wrongEffects:[{set:{curtain_failed:!0}}],gaze:{look:6,mirror:10,if:{any:[{not:{flag:{peeked:!0}}},{flag:{stage:3}}]},mirror1:5}},{id:"a1_curtain_unlock",type:"event",title:"1막 · 칸막이 커튼",bg:"art/a1_south.webp",lines:["딸깍. 자물쇠가 풀린다. 떨어지려는 고리를 손바닥으로 받친다."],choices:[{text:"커튼을 걷는다",goto:"a1_curtain_open"},{text:"아직 걷지 않는다",kind:"ghost",goto:"a1_north"}]},{id:"a1_curtain_open",type:"event",title:"1막 · 칸막이 커튼",bg:"art/a1_south.webp",art:"[배경] 열린 커튼 너머",noMirror:!0,lines:[{text:"커튼을 젖히자, 손에서 미끄러진 고리가 바닥을 친다. 쨍.",fx:"thud"},"커튼이 스르륵 젖혀지고, 안쪽이 드러난다. 뒷방 문. 그리고 가죽끈이 달린 진료의자.","커튼 고리가 떨어지는 소리에, 종이 더미 속의 닥터가 고개를 든다."],choices:[{text:"…",goto:"a1_found"}],onEnter:[{set:{curtain_open:!0}}]},{id:"a1_beaker",type:"event",title:"1막 · 비커",bg:"art/a1_beaker.webp",art:"[S2-5] 유리병 너머로 일그러져 비치는 여자의 얼굴",noMirror:!0,onFirst:[{set:{touched_beaker:!0}}],lines:["비커를 자세히 보려고 얼굴을 가까이 댄다.","해부체가 담긴 유리병 너머로, 여자의 얼굴이 오목하게, 볼록하게 일그러진다.","아름다운 얼굴이 아니다. 잠깐, 아주 잠깐.","닥터는 이쪽을 보지도 않고, 종이를 뒤지는 뒷모습으로 말한다.",{who:"닥터",text:"니, 니미럴년이… 여기가 니 집 안방인 줄 알아?"}],choices:[{text:"비커에 손을 댄 채 뒤통수를 빤히 본다",effects:[{add:{desire:1,trust:-1}}],reply:"어쩌라고. 여자는 눈도 깜빡이지 않는다.",goto:"a1_east"},{text:"손을 뗀다",effects:[{add:{trust:1}}],reply:"여자는 손가락을 떼고, 장갑에 묻은 무언가를 털어낸다.",goto:"a1_east"}],hotspots:[{id:"eye",label:"반짝이는 것",rect:[4,8,14,14],hidden:!0,once:!0,text:"병 속 해부체들 사이에, 하나만 유리로 된 눈이 섞여 있다.",eye:"eye_jar"}]},{id:"a1_south",type:"room",title:"1막 · 진료실 · 뒷방 문 쪽",bg:"art/a1_south.webp",art:"[배경] 어두운 뒷방 문, 작은 액자, 진료의자",intro:"뒷방 문 쪽. 하얀 방에서 유일하게 어두운 곳.",idle:"뒷방 문 쪽이다. 살펴볼 곳을 누르세요.",hotspots:[{id:"ratbox",label:"쥐 상자",rect:[52,40,40,18],if:{all:[{flag:{stage:2}},{not:{has:"item_backkey"}},{not:{flag:{rat_lost:!0}}}]},text:"덮개가 벗겨진 유리 상자. 반짝이는 것들이 이쪽을 본다.",goto:"a1_ratbox",fresh:!0},{id:"ratbox_after",label:"쥐 상자",rect:[52,40,40,18],if:{all:[{any:[{flag:{stage:2}},{flag:{stage:3}}]},{any:[{has:"item_backkey"},{flag:{rat_lost:!0}}]}]},text:"쥐들은 이제 이쪽을 보지 않는다."},{id:"door",label:"뒷방 문",rect:[0,26,22,64],text:["잠겨 있다.","문틈으로 차가운 바람과 약품 냄새가 새어 나온다. 안쪽에서 무언가 긁는 소리."],if:{not:{flag:{stage:3}}}},{id:"door_gap",label:"반쯤 열린 뒷방 문",rect:[0,26,22,64],fresh:!0,if:{flag:{stage:3}},text:["닥터는 등불을 들고 들어가면서 문을 다 닫지 않았다.","문틈 너머, 같은 크기의 유리병들이 선반에 줄지어 있다. 병마다 이름표.","구석에 사다리 하나. 천장으로 이어져 있다.","안쪽에서 물 끓는 소리. 그리고 콧노래."],textAgain:"물 끓는 소리. 콧노래는 아직 이어진다.",effects:[{clue:"hint_backroom"},{add:{gaze:15}}]},{id:"diploma",label:"작은 액자",rect:[26,28,18,16],text:["의과대학 졸업 증서. 수석.","이름 자리는 역시 긁혀 있다. 한때는 자랑이었을 것이다."]},{id:"straps",label:"발받침",rect:[56,60,32,30],text:"진료의자 발받침에 가죽끈이 달려 있다. 발목을 묶는 용도다.",effects:[{add:{suspicion:1}}]},{id:"eye",label:"반짝이는 것",rect:[4,88,12,10],hidden:!0,once:!0,text:"문 아래 틈에서 무언가 굴러 나와 있다.",eye:"eye_gap"}],mirror:{text:"거울에 비친 뒷방 문. 문 아래 틈으로 그림자가 지나간다. 저 안에 누가 있다."},triggers:[{id:"peek",if:{all:[{all:[{not:{flag:{peeked:!0}}},{gte:{gaze:100}}]},{not:{flag:{stage:3}}}]},goto:"a1_peek"},{id:"back3",if:{all:[{flag:{stage:3}},{gte:{gaze:100}}]},goto:"a1_return_early"},{id:"warn12",if:{all:[{not:{flag:{peeked:!0}}},{not:{flag:{stage:3}}},{gte:{gaze:70}},{lte:{gaze:99}},{not:{flag:{gaze_warned:!0}}}]},effects:[{set:{gaze_warned:!0}}],lines:["종이 넘기는 소리가 멎는다. …다시 넘어간다."]},{id:"warn3",if:{all:[{flag:{stage:3}},{gte:{gaze:70}},{lte:{gaze:99}},{not:{flag:{gaze_warned3:!0}}}]},effects:[{set:{gaze_warned3:!0}}],lines:["뒷방 문고리가 반쯤 돌다, 멈춘다."]}],choices:[{text:"닥터를 기다린다",if:{flag:{stage:3}},goto:"a1_return"},{text:"진료의자 쪽 →",kind:"ghost",goto:"a1_west",dir:"right"}],gaze:{look:6,mirror:10,if:{any:[{not:{flag:{peeked:!0}}},{flag:{stage:3}}]},mirror1:5},ambient:["문 너머에서 숨소리.","무언가 긁는 소리. 그리고 멎는다.","…","문틈 아래 그림자가 지나간다."],viewClass:{"lamp-off":{flag:{stage:3}}}},{id:"a1_west",type:"room",title:"1막 · 진료실 · 진료의자 쪽",bg:"art/a1_west.webp",art:"[배경] 진료의자, 액자, 천장에서 늘어진 진액",intro:"진료의자 쪽. 천장에서 늘어진 검은 것들이 가장 가까운 곳.",idle:"진료의자 쪽이다. 살펴볼 곳을 누르세요.",hotspots:[{id:"box",label:"진료의자 아래 함",rect:[38,86,26,12],if:{all:[{all:[{any:[{flag:{stage:2}},{flag:{stage:3}}]},{not:{flag:{box_open:!0}}}]},{not:{flag:{box_unlocked:!0}}}]},text:["진료의자 아래, 작은 쇠 함. 녹슨 자물쇠가 걸려 있다.","무언가 납작한 것이 안에서 미끄러지는 소리."],use:{item_backkey:{text:"녹슨 열쇠가 맞는다. 딸깍.",effects:[{set:{box_unlocked:!0}}],goto:"a1_box_unlock"},item_bar:{text:[{text:"쇠막대를 자물쇠 고리에 끼우고 비튼다. 끼이익—",fx:"thud"},"뒷방에서 소리가 멎는다. …다시 이어진다."],effects:[{set:{box_open:!0}},{add:{gaze:40,trust:-1}}],goto:"a1_box"}},useHint:"작은 열쇠 구멍. 아니면 비틀어 열 만한 것이라도.",fresh:!0},{id:"box_unlocked",label:"진료의자 아래 함",rect:[38,86,26,12],if:{all:[{flag:{box_unlocked:!0}},{not:{flag:{box_open:!0}}}]},goto:"a1_box_unlock"},{id:"drain",label:"진료의자 아래",rect:[4,84,26,14],if:{meta:"know_vault"},text:["진료의자 아래, 쇠창살 덮인 배수구. 축축한 바람이 올라온다.","…저 아래가 어디로 이어지는지, 왜인지 알 것 같다."],effects:[{set:{knows_drain:!0}}]},{id:"ceiling",label:"천장",rect:[8,2,84,18],text:"고개를 들어도 천장은 어둡다. 무언가 늘어져 있다는 것만 알 수 있다.",textAgain:"맨눈으로는 보이지 않는다. 다른 방법이 필요하다."},{id:"photo",label:"검은 얼룩 액자",rect:[50,36,26,14],text:["액자 속 사진. 하늘을 뒤덮은 검은 구름, 그 아래로 쏟아지는 무언가.","사진 아래 메모. ‘그날의 비.’"]},{id:"serum",label:"진액 통",rect:[0,58,18,18],text:["검은 진액이 든 큰 유리통. 꿀처럼 느리게 움직인다.","그 안에서 하얀 것들이 꿈틀거린다.","여자는 뚜껑을 살짝 들어 냄새를 맡았다가, 닫는 것을 잊었다.",{text:"통 가장자리에 붙어 있던 하얀 것 하나가 손수건 위로 떨어진다. 여자는 그것을 싸서 넣는다.",if:{flag:{maggot_serum:!0}}}],textAgain:"뚜껑이 열린 채다.",effects:[{set:{maggot_serum:!0},if:{not:{has:"item_maggot"}}},{give:"item_maggot",if:{not:{has:"item_maggot"}}},{clue:"clue_serum"},{set:{serum_open:!0}}]},{id:"chart",label:"의자 위의 종이",rect:[44,50,20,12],fresh:!0,if:{flag:{stage:3}},text:["진료의자 위에 종이 한 장. 닥터가 여자 주위를 돌 때 가운 주머니에서 떨어진 것이다.","아까 종이 더미에서 찾아 '이건 이따가' 하고 넣던 그 종이.","손님 기록지다. 이름 칸은 비어 있다.","‘원래 눈 — 보관.’ 그 칸에만 미리 표시가 되어 있다."],textAgain:"‘원래 눈 — 보관.’",effects:[{clue:"clue_chart"},{add:{suspicion:1}}]},{id:"chair",label:"진료의자",rect:[32,52,42,34],text:"치과 의자를 닮은 진료의자. 팔걸이에 손톱자국이 길게 나 있다."},{id:"eye",label:"반짝이는 것",rect:[66,60,8,8],hidden:!0,once:!0,text:"팔걸이 손톱자국 사이에 동그란 것이 박혀 있다.",eye:"eye_arm"},{id:"curtain_back",label:"커튼 뒷면",rect:[56,6,30,48],if:{flag:{curtain_open:!0}},sfx:"rail",goto:"a1_north"}],mirror:{text:["거울을 비스듬히 들자 천장이 비친다.","천장 틈에서 검은 진액이 실처럼 늘어져 내려온다. 진액은 위에서 온다.","천장 위에 무언가 있다."],effects:[{clue:"clue_ceiling"},{add:{suspicion:1}}]},triggers:[{id:"peek",if:{all:[{all:[{not:{flag:{peeked:!0}}},{gte:{gaze:100}}]},{not:{flag:{stage:3}}}]},goto:"a1_peek"},{id:"back3",if:{all:[{flag:{stage:3}},{gte:{gaze:100}}]},goto:"a1_return_early"},{id:"warn12",if:{all:[{not:{flag:{peeked:!0}}},{not:{flag:{stage:3}}},{gte:{gaze:70}},{lte:{gaze:99}},{not:{flag:{gaze_warned:!0}}}]},effects:[{set:{gaze_warned:!0}}],lines:["종이 넘기는 소리가 멎는다. …다시 넘어간다."]},{id:"warn3",if:{all:[{flag:{stage:3}},{gte:{gaze:70}},{lte:{gaze:99}},{not:{flag:{gaze_warned3:!0}}}]},effects:[{set:{gaze_warned3:!0}}],lines:["뒷방 문고리가 반쯤 돌다, 멈춘다."]}],choices:[{text:"닥터를 기다린다",if:{flag:{stage:3}},goto:"a1_return"},{text:"…위에 뭐가 있는지 알아요.",if:{all:[{meta:"know_source"},{not:{flag:{said_source:!0}}}]},effects:[{set:{said_source:!0}},{add:{suspicion:2}},{clue:"clue_ceiling"}],reply:[{who:"닥터",text:"……"},"곰방대가 닥터의 입에서 떨어질 뻔한다.",{who:"닥터",text:"…누가 보여 줬지? 아니, 대답하지 마."},{who:"닥터",text:"크크. 손님들은 가끔, 와 본 적 없는 곳을 기억하더군."}]},{text:"← 뒷방 문 쪽",kind:"ghost",goto:"a1_south",dir:"left"}],gaze:{look:6,mirror:10,if:{any:[{not:{flag:{peeked:!0}}},{flag:{stage:3}}]},mirror1:5},ambient:["천장에서 무언가 기어가는 소리.","팔걸이 가죽이 삐걱인다. 아무도 앉지 않았는데.","똑.","…"],viewClass:{"lamp-off":{flag:{stage:3}}}},{id:"a1_box_unlock",type:"event",title:"1막 · 함",bg:"art/a1_west.webp",lines:["뚜껑은 아직 닫혀 있다. 경첩이 녹슬어 있다."],choices:[{text:"뚜껑을 연다",effects:[{set:{box_open:!0,box_key:!0}}],reply:["뚜껑 경첩이 길게 운다."],goto:"a1_box"},{text:"아직 열지 않는다",kind:"ghost",goto:"a1_west"}]},{id:"a1_box",type:"event",title:"1막 · 함",bg:"art/a1_chair.webp",art:"[확대] 진료의자 아래 함",noMirror:!0,onEnter:[{clue:"clue_photos"}],lines:["함 안에는 사진 묶음. 손님들의 얼굴. 시술 전, 그리고 후.","후의 사진들은 모두 같은 각도로, 같은 입꼬리로 웃고 있다.","마지막 장은 비어 있다.",{text:"뒷방의 소리가 멎는다.",if:{flag:{box_key:!0}}},{text:"뒷방 문이 열린다.",fx:"thud"},"여자는 함을 닫고 일어선다. 아무것도 만지지 않은 얼굴로."],choices:[{text:"함을 닫는다",goto:"a1_chair"}]},{id:"a1_peek",type:"event",title:"1막 · 닥터",bg:"art/a1_peek.webp",art:"[S2-7] 손을 멈추고 눈알만 굴리는 닥터",pov:"doctor",onEnter:[{setv:{gaze:0}},{set:{peeked:!0}},{add:{trust:-1}}],lines:["뒤척이던 손을 뚝 멈춘다.","곰방대를 뻐끔이며, 눈알만 굴려 여자를 본다.","시선을 느꼈는지도 모르고, 여기저기 손을 대는군. 처음부터 다 보고 있었다.",{text:"내 비커에 손을 댔다.",if:{flag:{touched_beaker:!0}}},{text:"내 신문을 읽었다.",if:{clue:"clue_newspaper"}},{text:"서랍이 열려 있다.",if:{has:"item_magnifier"}},{text:"천장을 봤다. 거울로.",if:{clue:"clue_ceiling"}},{text:"진액 통 뚜껑이 열려 있다.",if:{flag:{serum_open:!0}}},{text:"…얼굴만 들여다보고 있군. 좋아. 그런 손님이 좋지.",if:{lte:{suspicion:1}}},"이 손님을 어떻게 할까."],choices:[{text:"못 본 척한다",effects:[{set:{peek_choice:"ignore"}}],reply:"…조금 더 지켜보자. 크크.",goto:"a1_north"},{text:"머릿속에 적어 둔다",effects:[{set:{peek_choice:"record"}},{add:{trust:-1}}],reply:"만진 것, 본 것. 하나도 빠짐없이.",goto:"a1_north"},{text:"다가가 제지한다",effects:[{set:{peek_choice:"stop"}},{add:{trust:-1}},{add:{trust:-1}}],reply:[{who:"닥터",text:"…구경은 공짜가 아니야."},"닥터는 다시 종이 더미로 고개를 숙인다. 눈은 여전히 이쪽이다."],goto:"a1_north"}]},{id:"a1_found",type:"event",title:"1막 · 하얀 진료실",bg:"art/a1_papers.webp",art:"[S2-4] 종이를 찾아낸 닥터",noMirror:!0,lines:["한참 책상을 뒤지던 닥터가 종이 사이에서 무언가를 찾고, 번쩍 허리를 세운다.",{who:"닥터",text:"찾았다. 크크. 이건 이따가."},"닥터는 종이를 가운 주머니에 쑤셔 넣는다.",{who:"여자",text:"전 얼굴이 재산인 사람이라, 회복이 빨리 되어야 해요. 아주 빨리. 이해해요?"},{who:"여자",text:"다음 달에 다시 카메라 앞에 서야 해요. 새 주연이 정해지기 전에."},{who:"여자",text:"그런데 여기, 간판도 없던데요."},{who:"닥터",text:"(정색하며, 낮은 목소리로) 시궁창 같은 지하에서 쥐새끼처럼 숨어 지낼 뿐. 실력은 의심할 바 없어."}],choices:[{text:"노트의 단서를 내민다",if:{all:[{clues:{gte:1}},{not:{flag:{present1:!0}}}]},effects:[{set:{present1:!0}}],prompt:"‘실력은 의심할 바 없다’는 닥터에게.",present:{clue_license:{reply:[{who:"여자",text:"실력이 그렇게 좋으면, 면허는 왜 긁혀 있어?"},"닥터의 웃음이 잠깐 멎는다.",{who:"닥터",text:"이름? 첫 번째 손님한테 줘 버렸어."}],effects:[{add:{suspicion:1}},{set:{know_first_fail:!0}}]},clue_specimen:{reply:[{who:"여자",text:"받침대의 빈 이름표. 나 앉히려고 비워 둔 거지?"},{who:"닥터",text:"크크. 눈치 빠른 손님은 오래 못 가는데."}],effects:[{add:{suspicion:1,trust:-1}}]},clue_shelf:{reply:[{who:"여자",text:"받침대 그것들, 견본치고 손때가 탔던데."},{who:"닥터",text:"다들 웃으면서 나갔어. 벽을 짚으면서."}],effects:[{add:{suspicion:1}}]},clue_newspaper:{reply:[{who:"여자",text:"신문에 실종된 가수 있던데."},"닥터는 깜빡이지 않는다.",{who:"닥터",text:"노래 좋았지."},{who:"닥터",text:"…마지막 무대도."}],effects:[{add:{suspicion:1}}]},hint_telegram:{reply:[{who:"닥터",text:"(훑어보고) 카메라가 못 잡는 눈이라. …크크."}],effects:[{add:{trust:1}}]}},presentDefault:{reply:[{who:"닥터",text:"그게 뭐? 손님 물건이야?"},"닥터는 시큰둥하게 고개를 돌린다.","닥터의 어깨에서 힘이 빠진다. 이 손님은 아무것도 모른다는 얼굴이다."],effects:[{add:{trust:1}},{add:{suspicion:-1}}]}},{text:"…",goto:"a1_face"}]},{id:"a1_face",type:"event",title:"1막 · 얼굴",bg:"art/a1_face.webp",art:"[S2-9] 여자의 얼굴 윤곽을 따라가는 닥터의 손끝",noMirror:!0,lines:["닥터가 여자에게 휙 얼굴을 들이댄다.","손끝이 여자의 얼굴 윤곽을 따라 움직인다. 닥터의 눈이 무언가에 빙의된 듯 스르르 풀린다.",{text:"선글라스가 벗겨지고, 선명한 이목구비가 드러난다.",effects:[{set:{face_hidden:!1}}]},{who:"여자",text:"만지지 마요. 이 얼굴, 보험 들어 있거든요."},{who:"닥터",text:"아무리 높게 떠 있던 별도, 떨어지면 돌덩이야."}],choices:[{text:"끝까지 듣는다",reply:[{who:"닥터",text:"…돌덩이는 깎으면 돼. 그게 내 일이고."},{who:"여자",text:"…손은 안 떨려요? 그 연세에."},{who:"닥터",text:"(말투가 바뀌며) 이 나이에 이 손 가진 놈, 어디 또 있으면 데려와 봐."}],goto:"a1_rats"},{text:"말을 끊는다",reply:[{who:"여자",text:"별 얘기는 됐고요. 손은 안 떨려요? 그 연세에."},{who:"닥터",text:"(말투가 바뀌며) 이 나이에 이 손 가진 놈, 어디 또 있으면 데려와 봐."},"닥터의 손끝이 얼굴에서 떨어진다."],effects:[{add:{trust:-1}},{add:{cut:1}}],goto:"a1_rats"}]},{id:"a1_rats",type:"event",title:"1막 · 쥐",bg:"art/a1_rats.webp",art:"[S2-10] 덮개 천 아래 연구용 쥐 상자",noMirror:!0,lines:["닥터는 테이블로 가서 덮어 두었던 천을 벗긴다.","유리 상자 안, 살아 있는 연구용 쥐 여러 마리. 작은 몸통들이 서로를 타고 넘는다.","몇 마리의 눈이 이상하게 반짝인다. 유리처럼."],choices:[{text:"…",goto:"a1_expr"}],onEnter:[{set:{stage:2}},{setv:{gaze:0}},{set:{gaze_warned:!1}}]},{id:"a1_expr",type:"event",title:"1막 · 쥐",bg:"art/a1_expr.webp",art:"[S2-11] 오묘한 여자의 표정",noMirror:!0,lines:["여자의 표정이 오묘하게 변한다."],choices:[{text:"반짝이는 눈에 매혹된다",effects:[{add:{desire:1}}],reply:"역겹지 않다. 오히려… 저 반짝임이 부럽다.",goto:"a1_rats_leave"},{text:"쥐한테도 돈 받았으려나",reply:"여자는 심드렁하게 어깨를 으쓱한다.",goto:"a1_rats_leave"},{text:"눈을 가늘게 뜨고 쥐의 눈을 본다",effects:[{add:{suspicion:1}}],reply:"저건 원래 눈이 아니다. 박아 넣은 것이다.",goto:"a1_rats_leave"}]},{id:"a1_rats_leave",type:"event",title:"1막 · 쥐",bg:"art/a1_rats.webp",lines:[{who:"닥터",text:"잠깐. 준비할 게 있어."},{who:"닥터",text:"아무것도 만지지 마. 특히 걔들은."},"닥터는 뒷방으로 들어간다. 문이 반쯤 닫힌다.",{text:"책상 서랍은 아직 잠겨 있다.",if:{not:{has:"item_magnifier"}}},{text:"[안내] 풀지 못한 자물쇠는 홀로 남게 되면 다시 풀 수 있습니다.",if:{not:{has:"item_magnifier"}}}],choices:[{text:"…",goto:"a1_south"}]},{id:"a1_chair",type:"event",title:"1막 · 진료의자",bg:"art/a1_chair.webp",art:"[S3-1] 진료의자",noMirror:!0,lines:["들뜬 닥터가 콧노래를 부른다. 춤을 추듯 여자 주위를 돌며 가운을 입힌다.","동선을 끊지 않고, 여자를 휙 끌어다 진료의자에 앉힌다.",{text:"여자의 무릎 위로 책자가 턱, 떨어진다.",fx:"thud"},"순식간에 벌어진 일이라 여자는 침을 꼴깍 삼킨다.",{who:"여자",text:"면허도 없는 손에 눈을 맡기라고?",if:{clue:"clue_license"}},{who:"여자",text:"소문이 좋진 않던데요.",if:{not:{clue:"clue_license"}}},{who:"닥터",text:"걱정 마. 소문 그대로니까."},{who:"닥터",text:"시기하는 놈들이 짖는 거야. 인류를 갈아엎을 연구를, 그 머저리들이."},{who:"닥터",text:"첫 번째는… 서둘렀지. 이번엔 안 서둘러.",if:{flag:{know_first_fail:!0}},effects:[{clue:"hint_first"}]}],choices:[{text:"책자를 넘긴다",goto:"a1_book"}]},{id:"a1_book",type:"event",title:"1막 · 책자",bg:"art/a1_book.webp",art:"[S3-2] 인공 눈알 삽입 챕터",lines:["인간과 동물 사이 이종 결합 수술 사진들이 한 장씩 넘어간다.","마지막 장. 인공 눈알 삽입. 쥐, 원숭이… 인조 눈알이 박힌 동물들.","그리고 사람에게 쓸 견본 세 가지.","[안내] 거울을 꺼내 자신의 눈과 비교해 볼 수 있습니다."],mirror:{text:"손거울 속 자신의 눈동자와 책자 속 사진을 번갈아 본다. 이 눈은… 너무 평범하다."},choices:[{text:"황금빛 눈알을 콕 찍는다",effects:[{add:{desire:2}},{set:{eye_choice:"gold"}}],goto:"a1_gold"},{text:"푸른 눈알을 고른다",effects:[{add:{suspicion:1}},{set:{eye_choice:"blue"}}],reply:["사진 옆 작은 글씨. ‘견본 L.’",{text:"L. 신문 속 실종된 가수. 그녀의 푸른 눈은 유명했다.",if:{clue:"clue_newspaper"}},{who:"닥터",text:"보는 눈은 있군. 크크."}],goto:"a1_maggots"},{text:"닥터에게 맡긴다",effects:[{add:{trust:2}},{set:{eye_choice:"doctor"}}],reply:{who:"닥터",text:"현명해. 아주 현명해. 내 최신작을 주지."},goto:"a1_maggots"}]},{id:"a1_gold",type:"event",title:"1막 · 황금의 눈",bg:"art/a1_book.webp",art:"[S3-2] 황금빛 눈알 사진",noMirror:!0,lines:["그제야 만족한 듯 활짝 웃는다. 낯가리던 모습은 어디 갔는지, 목소리가 한껏 올라간다.",{text:"사진 앞에서 여자의 손가락이 잠깐 멈춘다. 유리처럼 반짝이던 얼굴들. 어디선가 본 것 같다.",if:{ending:"golden"},effects:[{add:{desire:-1}}]},{who:"여자",text:"이걸로 할게요!"},"여자의 목소리가 무대 위의 목소리로 바뀐다.",{who:"여자",text:"가을날 곡식처럼, 고대 해적왕이 숨긴 황금처럼, 눈부시게 빛나는, 금귤빛의 홍채!"},{who:"여자",text:"백설공주의 시린 피부처럼, 백사장에 비춰 내리는 새벽 달빛처럼, 푸른빛이 감도는 백색의 흰자!"},{who:"여자",text:"(초롱초롱한 눈으로) 제가, 딱, 원하던 거예요."}],choices:[{text:"…",goto:"a1_maggots"}]},{id:"a1_maggots",type:"event",title:"1막 · 구더기",bg:"art/a1_maggots.webp",art:"[S3-3] 구석에서 구더기를 줍는 닥터",noMirror:!0,lines:["여자가 닥터 쪽으로 고개를 돌린다.","닥터는 구석에 쪼그려 앉아, 구더기를 의료 집게로 하나씩 집어 비커에 모으고 있다.",{text:"모자를 던져 둔 그 구석이다. 모자 챙에서 구더기가 기어 나온다.",if:{flag:{hat_place:"desk"}}},{who:"닥터",text:"역사에 길이 남을 ‘Mole Doctor’의 눈알 이식 수술법, 그 인간 수혜자!"}],choices:[{text:"끝까지 듣는다",reply:[{who:"닥터",text:"그토록 찾던 게… 하늘에서… 비처럼 후두두둑! 키키키키, 거참! 어이가 없어서!"},{who:"닥터",text:"멍청이들은 이걸 하늘의 재앙이나 저주라고 두려워하지."},"닥터는 구더기를 큰 유리통에 붓는다. 검고 끈적이는 진액. 사랑스럽게 통을 쓰다듬는다."],goto:"a1_cut"},{text:"말을 끊는다",reply:[{who:"여자",text:"구더기 자랑은 수술 끝나고 들을게요."},{who:"닥터",text:"……"},"집게가 비커 가장자리를 탁, 친다.","닥터는 구더기를 큰 유리통에 붓는다. 검고 끈적이는 진액. 사랑스럽게 통을 쓰다듬는다."],effects:[{add:{trust:-1}},{add:{cut:1}}],goto:"a1_cut"}]},{id:"a1_cut",type:"event",title:"1막 · 시연",bg:"art/a1_cut.webp",art:"[S3-4] 칼로 자신의 팔을 긋는 닥터",noMirror:!0,lines:[{text:"닥터가 칼을 들어, 자신의 팔을 뚝 긋는다.",fx:"thud"},"피가 바닥에 떨어질 만큼 깊다.","여자는 충격에 입을 틀어막는다.","닥터는 나무 숟가락으로 유리통을 휘휘 젓는다. 숟가락을 들었다 놓으며 점성을 본다. 꿀처럼 찐득해질 때까지."],choices:[{text:"…",goto:"a1_serum"}]},{id:"a1_serum",type:"event",title:"1막 · 시연",bg:"art/a1_serum.webp",art:"[S3-5] 상처 위에 올린 진액과 구더기",noMirror:!0,lines:["한 움큼 덜어낸 진액을 상처 위에 올린다. 상처와 미처 으깨지지 않은 구더기가 뒤엉켜 꿈틀거린다.","닥터의 표정이 황홀하다.",{who:"닥터",text:"이걸 봐! 꿈틀거리며 비명을 지르는 게 들리지 않나?"},{who:"닥터",text:"검은 구름들과 함께 이것들이 땅으로 내려온 걸, 너도 보았겠지?"},{who:"닥터",text:"이제 모든 눈은 이 기적을 보게 되겠지. 벌레라고 짓밟던 놈들까지도. 키키키."},"닥터가 크게 숨을 내쉬고 구더기를 털어낸다.","칼자국이 옅어져 있다."],choices:[{text:"의심을 말한다",effects:[{add:{suspicion:1}}],reply:[{who:"여자",text:"지난 몇 년간 벌레비가 내렸지만, 상처를 치유한다는 얘기는 들어 보지도 못했는데요?"},{who:"여자",text:"무슨 비겁한 수법을 쓴 건 아니에요?"}],goto:"a1_messiah"},{text:"말없이 옅어진 상처를 들여다본다",effects:[{add:{desire:1}}],reply:"찡그리고 있지만, 눈을 뗄 수 없다.",goto:"a1_messiah"}]},{id:"a1_messiah",type:"event",title:"1막 · 메시아",bg:"art/a1_messiah.webp",art:"[S3-6] 빛 아래 연기를 내뿜는 닥터",noMirror:!0,lines:["닥터, 연기를 길게 내뿜는다. 눈을 감았다 뜬다.",{who:"닥터",text:"그걸 알려주면 쓰겠나. 크크크."},{who:"닥터",text:"영원한 생명… 이 지구에 없던 것으로 세상은 뒤집힐 거야. 이 땅의 타락한 모든 것이 전멸되고 새살이 돋아날 거라고."}],choices:[{text:"끝까지 듣는다",reply:[{who:"닥터",text:"이것이 곧 신이 내려준 축복. 아니, 신 그 자체. 자신의 살을 내어서… 생명을 주는, 그토록 고대해 온 고귀한… 메시아의 귀환!"},{who:"닥터",text:"그리고 이 사실을 최초로 증명하는 건, 역시 나여야겠지. 키키키."}],effects:[{clue:"hint_messiah"}],goto:"a1_messiah2"},{text:"말을 끊는다",reply:[{who:"여자",text:"그래서, 언제 시작해요?"},{who:"닥터",text:"……"},"닥터의 입꼬리가 내려간다."],effects:[{add:{trust:-1}},{add:{cut:1}}],goto:"a1_messiah2"}]},{id:"a1_messiah2",type:"event",title:"1막 · 메시아",bg:"art/a1_messiah.webp",art:"[S3-6] 빛 아래 연기를 내뿜는 닥터",noMirror:!0,lines:["닥터는 곰방대를 탁탁 턴다."],choices:[{text:"노트의 단서를 내민다",if:{all:[{clues:{gte:1}},{not:{flag:{present2:!0}}}]},effects:[{set:{present2:!0}}],prompt:"‘메시아의 귀환’을 외치는 닥터에게.",present:{clue_ceiling:{reply:[{who:"여자",text:"그 메시아, 천장 위에서 내려오는 거잖아."},"닥터가 처음으로 웃음을 지운다.",{who:"닥터",text:"…위는 보지 마. 거기는 손님 자리가 아니야."}],effects:[{add:{suspicion:1}},{set:{ask_ceiling:!0}}]},clue_serum:{reply:[{who:"여자",text:"통 뚜껑 열려 있던데. 귀하신 메시아님이 다 말라 가더라."},{who:"닥터",text:"…네가 열었군."}],effects:[{add:{trust:-1,suspicion:1}}]},hint_messiah:{reply:[{who:"여자",text:"자기 살을 내준다면서. 그 메시아는 동의는 했어?"},{who:"닥터",text:"…동의는 손님들이 하지."}],effects:[{add:{suspicion:1}}]}},presentDefault:{reply:[{who:"닥터",text:"크크. 그딴 걸로 신을 반박하려고?"},"닥터는 안심한 얼굴로 곰방대를 다시 문다."],effects:[{add:{trust:1}},{add:{suspicion:-1}}]}},{text:"…",goto:"a1_alone"}]},{id:"a1_alone",type:"event",title:"1막 · 홀로",bg:"art/a1_west.webp",art:"[배경] 진료의자",noMirror:!0,onEnter:[{set:{stage:3}},{setv:{gaze:0}}],lines:[{who:"닥터",text:"동의서를 가져오지."},{who:"닥터",text:"얌전히 있어. 이번엔 정말로."},{text:"천장 위에서 무언가 긁는 소리. 한 번, 그리고 멎는다.",sfx:"scratch",if:{guide:1}},{text:"닥터가 천장을 올려다본다.",if:{guide:1}},{who:"닥터",text:"…조용하군. 평소엔 저렇게 안 조용한데.",if:{guide:1}},"닥터가 등불을 들고 뒷방으로 들어간다. 문은 반쯤 열린 채다.","진료실이 한 톤 어두워진다. 여자 혼자 남는다.",{text:"책상 서랍은 아직 잠겨 있다.",if:{not:{has:"item_magnifier"}}},"[안내] 닥터가 돌아오기 전에 남은 것을 살펴볼 수 있습니다. 준비가 되면 ‘닥터를 기다린다’."],choices:[{text:"…",goto:"a1_west"}]},{id:"a1_return",type:"event",title:"1막 · 동의서",bg:"art/a1_messiah.webp",art:"[S3-6] 닥터",noMirror:!0,lines:["뒷방 문이 열린다. 닥터가 종이 한 장을 흔들며 돌아온다."],choices:[{text:"…",goto:"a1_plead"}]},{id:"a1_return_early",type:"event",title:"1막 · 동의서",bg:"art/a1_peek.webp",art:"[S2-7] 닥터의 눈",noMirror:!0,onEnter:[{add:{trust:-1}}],lines:["뒷방 문이 생각보다 일찍 열린다.",{who:"닥터",text:"…얌전히 있으랬지."},"닥터가 종이 한 장을 흔든다. 눈은 웃지 않는다."],choices:[{text:"…",goto:"a1_plead"}]},{id:"a1_plead",type:"event",title:"1막 · 애원",bg:"art/a1_plead.webp",art:"[S3-7] 얼굴을 감싸는 여자",noMirror:!0,lines:[{who:"여자",text:"(다급하게) 그럼요! 당신이 날 살린다는 걸 믿어요! 어서 시작해요, 닥터!"},{who:"여자",text:"카메라는 거짓말을 안 해요. 이 눈은 이제 아무것도 못 잡아요."},{who:"여자",text:"(두 손으로 얼굴을 감싸며) 이 칙칙한 얼굴… 전 눈 뜨고 볼 수 없어요!!"}],choices:[{text:"…",goto:"a1_coins"}]},{id:"a1_coins",type:"event",title:"1막 · 금화",bg:"art/a1_coins.webp",art:"[S3-8] 금화를 쑤셔 넣으며 옷깃을 부여잡는 여자",noMirror:!0,lines:["여자는 주머니에서 금화를 황급히 꺼내, 닥터의 주머니에 마구 집어넣으며 옷깃을 부여잡는다.",{text:"순찰병에게 한 닢을 줘 버린 탓에 모자란다. 여자는 진주 목걸이까지 풀어 쥐여 준다.",if:{lte:{coins:2}}},{text:"금화 몇 개가 바닥에 떨어진다. 반쯤 녹은 구더기가 검은 진액 위를 꿈틀거린다. 살아남은 두어 마리가 책장 밑으로 기어 들어간다.",effects:[{add:{coins:-3}}]},{who:"여자",text:"아, 이 더러운 세상."},{who:"여자",text:"(사이) 그럼 이제 향기 가득한 꽃밭으로 바뀌겠죠?"},{who:"닥터",text:"(시큰둥하게) 꽃밭은 무슨. 눈깔이 바뀌는 거지."},{who:"여자",text:"아무튼! 눈이 바뀌는 거 맞잖아요."}],choices:[{text:"…",goto:"a1_consent"}]},{id:"a1_consent",type:"event",title:"1막 · 동의서",bg:"art/a1_consent.webp",art:"[S2-8] 동의서와 펜",noMirror:!0,lines:["닥터가 미소를 지으며, 아까 주머니에 넣었던 종이와 펜을 건넨다.",{who:"닥터",text:"서명해. 다들 그렇게 하지. 읽는 놈은 못 봤고. 크크.",if:{guide:2}},"수술 동의서. 신체 포기 각서와 다를 바 없다. 맨 아래에 경고 문구가 아주 작게 적혀 있다.",{who:"닥터",text:"조심해, 아가씨. 수은과 염은 까딱 잘못하면 손가락을 녹여 버리지. 크크."}],choices:[{text:"돋보기로 작은 글씨를 읽는다",if:{all:[{has:"item_magnifier"},{not:{clue:"clue_consent"}}]},effects:[{clue:"clue_consent"},{add:{suspicion:1}}],reply:["돋보기 아래로 작은 글씨가 떠오른다.","‘시술 후 시야는 보장하지 않는다.’","‘적출된 원래의 안구는 시술자의 소유로 한다.’"]},{text:"작은 글씨를 읽어 본다",if:{not:{has:"item_magnifier"}},reply:"너무 작다. 맨눈으로는 읽을 수 없다. 어딘가 돋보기가 있었다면…"},{text:"노트의 단서를 내민다",if:{all:[{clues:{gte:1}},{not:{flag:{present3:!0}}}]},effects:[{set:{present3:!0}}],prompt:"서명하기 전에, 동의서를 내미는 닥터에게.",present:{clue_consent:{reply:[{who:"여자",text:"‘시야는 보장하지 않는다’. 이거, 무슨 뜻이야?"},"닥터는 대답 대신 펜 뚜껑을 연다.",{who:"닥터",text:"…글씨가 작지? 다들 그 줄은 안 읽더라."}],effects:[{add:{suspicion:1}}]},clue_specimen:{reply:[{who:"여자",text:"빈 이름표에 내 이름 쓸 거면, 계약서에도 적어 놔."},{who:"닥터",text:"…적어 두지. 크크. 아주 크게."}],effects:[{add:{suspicion:1}}]},clue_license:{reply:[{who:"여자",text:"면허도 없는 사람 서명란은 어디야?"},{who:"닥터",text:"면허는 종이야. 실력은 손에 있고."}],effects:[{add:{suspicion:1}}]}},presentDefault:{reply:[{who:"닥터",text:"서명하기 싫으면 싫다고 해. 빙빙 돌리지 말고."}]}},{text:"지금까지 본 것을 정리한다",if:{all:[{clues:{gte:3}},{not:{flag:{hyp_done:!0}}}]},goto:"a1_hyp1"},{text:"서명한다",effects:[{set:{route:"surgery"}}],goto:"a1_sign"},{text:"서명을 거부한다",effects:[{set:{route:"escape"}}],goto:"a1_refuse"},{text:"서명하기 전에 증거를 요구한다",if:{any:[{all:[{clues:{gte:4}},{gte:{suspicion:3}},{flag:{hypothesis_1:!0}}]},{all:[{flag:{said_source:!0}},{clues:{gte:2}}]}]},effects:[{set:{route:"truth"}},{meta:{truth_entered:!0}}],goto:"a1_truth"},{text:"…잠깐.",kind:"ghost",if:{all:[{guide:3},{not:{any:[{all:[{clues:{gte:4}},{gte:{suspicion:3}},{flag:{hypothesis_1:!0}}]},{all:[{flag:{said_source:!0}},{clues:{gte:2}}]}]}}]},reply:[{who:"여자",text:"…뭔가 걸린다. 뭔지는 모르겠다."},{who:"여자",text:"뭐, 상관없나."}]}]},{id:"a1_hyp1",type:"event",title:"1막 · 추리",bg:"art/a1_license.webp",art:"[추리] 면허증",noMirror:!0,onEnter:[{set:{hyp_done:!0}}],lines:["펜을 쥔 채, 이 방에서 본 것들을 맞춰 본다.","닥터가 면허를 잃은 이유는?"],choices:[{text:"수술 중 의료 사고",goto:"a1_hyp2"},{text:"불법 시술과 금지된 연구",effects:[{set:{hyp_a:!0}}],goto:"a1_hyp2"},{text:"전쟁 징집 거부",goto:"a1_hyp2"}]},{id:"a1_hyp2",type:"event",title:"1막 · 추리",bg:"art/a1_drawer.webp",art:"[추리] 유리 눈알",noMirror:!0,lines:["받침대 위 이름표 붙은 유리 눈알들은?"],choices:[{text:"장식용 견본",reply:"…그렇게 믿고 싶다.",goto:"a1_consent"},{text:"이전 환자들에게서 나온 것",effects:[{set:{hypothesis_1:!0},if:{flag:{hyp_a:!0}}}],reply:[{text:"면허를 빼앗긴 의사. 이름표 붙은 눈. 서명된 동의서 묶음. 조각이 맞아떨어진다.",if:{flag:{hyp_a:!0}}},{text:"그럴듯하다. 하지만 아직 무언가 맞지 않는다.",if:{not:{flag:{hyp_a:!0}}}}],goto:"a1_consent"},{text:"동물 실험용",reply:"…쥐에게 이름표를 붙이진 않을 것이다.",goto:"a1_consent"}]},{id:"a1_sign",type:"event",title:"1막 · 서명",bg:"art/a1_consent.webp",art:"[S2-8] 서명하는 손",noMirror:!0,lines:["여자는 과감하게 서명한다.",{who:"닥터",text:"크하! 돈 많은 손님이구먼. (뭐가 우스운지 깔깔 웃으며)"},"그리고 닥터는 종이 한 장을 더 내민다.",{who:"닥터",text:"여기도 하나. '번창하세요', 이런 식으로. 크크."},"여자는 웃으며 한 장 더 서명한다.",{who:"닥터",text:"준비하고 올게. 얌전히 있어."},"닥터는 수술 도구를 챙겨 뒷방으로 들어간다.",{text:"철컥. 철문이 잠기는 소리.",fx:"thud"}],choices:[{text:"…",goto:"e2_start"}],onEnter:[{set:{signed:!0}}]},{id:"a1_refuse",type:"event",title:"1막 · 거부",bg:"art/a1_south.webp",art:"[배경] 어두운 뒷방 문",noMirror:!0,lines:[{who:"여자",text:"…조금 더 생각해 볼게요."},"닥터의 미소가 그대로 굳는다.",{who:"닥터",text:"그럼 준비가 더 필요하겠군."},"닥터는 뒷방으로 사라진다.",{text:"여자가 철문 손잡이를 돌린다. 열리지 않는다. 밖에서 잠겨 있다.",fx:"thud"}],choices:[{text:"…",goto:"e2_start"}]},{id:"a1_truth",type:"event",title:"1막 · 증거",bg:"art/a1_peek.webp",art:"[S2-7] 닥터의 눈",noMirror:!0,lines:[{who:"여자",text:"서명하기 전에 증명해 보세요. 면허는 왜 잃었는지. 받침대의 눈은 누구 건지."},"닥터의 눈이, 처음으로 깜빡인다.",{who:"닥터",text:"…크크. 증명이라. 그건 내 전문이지."},"닥터가 가운 안쪽에서 뒷방 열쇠를 꺼낸다."],choices:[{text:"…",goto:"t2_lab_in"}]}],vt=[{id:"e2_start",type:"event",title:"2막 · 갇힌 진료실",bg:"art/a1_south.webp",art:"[배경] 어두운 뒷방 문",noMirror:!0,onEnter:[{set:{steps:0}},{if:{meta:"know_vault"},add:{steps:-13}}],lines:[{text:"뒷방에서 금속 부딪치는 소리. 철문은 잠겨 있다.",if:{flag:{signed:!0}}},{text:"철문 손잡이를 다시 돌려 본다. 꿈쩍도 하지 않는다.",if:{not:{flag:{signed:!0}}}},{who:"여자",text:"서명까지 받고 가두기까지. 꼼꼼하네.",if:{flag:{signed:!0}}},{who:"여자",text:"손님을 가둬 두는 서비스까지. 친절하기도 해라.",if:{not:{flag:{signed:!0}}}},"뒷방에서 금속 끄는 소리. 무언가를 준비하고 있다.","다른 출구가 있을 것이다. 이런 지하라면, 물이 빠지는 길이라도.",{text:"이번엔 안다. 진료의자 아래.",if:{meta:"know_vault"}},{text:"…아니면, 얌전히 수술대에 누워 기다려도 된다.",if:{flag:{signed:!0}}}],choices:[{text:"출구를 찾는다",goto:"e2_north"}]},{id:"e2_lie",type:"event",title:"2막 · 수술대",bg:"art/s2_table.webp",art:"[S4-2] 수술대",noMirror:!0,lines:["여자는 코트를 벗어 의자에 걸고, 수술대에 눕는다.","천장의 얼룩을 센다. 하나, 둘.",{text:"뒷방 문이 열린다.",fx:"thud"},{who:"닥터",text:"…크크. 착한 손님이야."}],onEnter:[{set:{route:"surgery"}}],choices:[{text:"…",goto:"s2_table"}]},{id:"e2_north",type:"room",title:"2막 · 대기실 · 책상 쪽",bg:"art/a1_north.webp",art:"[배경] 책상",gaze:{var:"steps",label:"발소리",look:7,mirror:5,tick:!0},idle:"책상 쪽이다. 출구가 될 만한 것을 찾자.",hotspots:[{id:"tray",label:"수술 도구 트레이",rect:[56,70,40,24],text:["종이 더미 아래 수술 도구 트레이. 메스 하나가 삐져나와 있다.","여자는 메스를 장갑 속에 밀어 넣는다."],textAgain:"트레이에는 이제 쓸 만한 게 없다.",effects:[{give:"item_scalpel"}],sprite:"obj/tray.png"},{id:"gramophone",label:"축음기",rect:[2,46,22,24],if:{not:{has:"item_record_memo"}},text:["축음기 음반 「달빛」. 옆에 연필로 ‘4분 10초’.","여자는 그 숫자를 외워 둔다."],effects:[{give:"item_record_memo"}]},{id:"license",label:"면허증 액자",rect:[16,28,32,24],text:"긁힌 이름. 지금 그게 중요한 게 아니다."},{id:"curtain",label:"걷힌 커튼",rect:[34,6,30,62],sfx:"rail",goto:"e2_west"}],triggers:[{id:"caught",if:{gte:{steps:100}},goto:"e2_caught"}],choices:[{text:"수술대에 눕는다",kind:"ghost",if:{flag:{signed:!0}},goto:"e2_lie"},{text:"선반 쪽 →",kind:"ghost",goto:"e2_east",dir:"right"}],ambient:["뒷방에서 칼 가는 소리.","…","똑."],viewClass:{"lamp-off":{gte:{steps:0}},vignette:{gte:{steps:0}}}},{id:"e2_east",type:"room",title:"2막 · 대기실 · 선반 쪽",bg:"art/a1_east.webp",art:"[배경] 선반, 실험대",gaze:{var:"steps",label:"발소리",look:7,mirror:5,tick:!0},idle:"선반 쪽이다. 출구가 될 만한 것을 찾자.",hotspots:[{id:"pipemap",label:"벽 메모",rect:[82,32,16,22],text:["벽에 붙은 메모 중 하나가 배관도다. 글씨 대신 기호뿐이다.","‘첫 갈림길 — △ 수장고 / × 하수.’","‘둘째 갈림길 — ○ 지상 / × 막힘.’"],textAgain:"△ 수장고. ○ 지상. × 는 피할 것.",effects:[{set:{pipe_map:!0}},{clue:"hint_pipemap"}]},{id:"bucket",label:"양동이",rect:[46,86,14,12],if:{not:{has:"item_maggot"}},text:"구더기가 떠 있는 양동이. 한 마리를 손수건에 싸서 챙긴다.",effects:[{give:"item_maggot"}]},{id:"jars",label:"해부체 유리병",rect:[4,16,62,28],text:"병 속의 것들이 이쪽을 본다. 도와줄 생각은 없어 보인다."},{id:"irondoor",label:"철문",rect:[20,28,18,40],text:["손잡이를 돌린다. 덜컹— 지하 전체가 울린다.","뒷방의 흥얼거림이 뚝 끊긴다."],textAgain:"열리지 않는다. 더 흔들 필요는 없다.",effects:[{add:{steps:10}}]}],triggers:[{id:"caught",if:{gte:{steps:100}},goto:"e2_caught"}],choices:[{text:"수술대에 눕는다",kind:"ghost",if:{flag:{signed:!0}},goto:"e2_lie"},{text:"← 책상 쪽",kind:"ghost",goto:"e2_north",dir:"left"}],ambient:["병 속의 것들이 이쪽으로 몸을 돌린다.","…","똑. 똑."],viewClass:{"lamp-off":{gte:{steps:0}},vignette:{gte:{steps:0}}}},{id:"e2_south",type:"room",title:"2막 · 진료실 · 뒷방 문 쪽",bg:"art/a1_south.webp",art:"[배경] 뒷방 문",gaze:{var:"steps",label:"발소리",look:7,mirror:5,tick:!0},idle:"뒷방 문 쪽이다. 닥터가 저 안에 있다.",hotspots:[{id:"door",label:"뒷방 문 (귀를 댄다)",rect:[0,26,22,64],text:["문에 귀를 댄다. 쇠를 가는 소리. 흥얼거림.",{who:"여자",text:"…지금은 바쁘네."}],effects:[{add:{steps:8}}],textAgain:"문 너머에서 쇠를 가는 소리. 아직이다.",pauseTick:2e4}],triggers:[{id:"caught",if:{gte:{steps:100}},goto:"e2_caught"}],choices:[{text:"수술대에 눕는다",kind:"ghost",if:{flag:{signed:!0}},goto:"e2_lie"},{text:"진료의자 쪽 →",kind:"ghost",goto:"e2_west",dir:"right"}],ambient:["칼 가는 소리가 멎는다.","문손잡이가 아주 조금 돈다.","…"],viewClass:{"lamp-off":{gte:{steps:0}},vignette:{gte:{steps:0}}}},{id:"e2_west",type:"room",title:"2막 · 진료실 · 진료의자 쪽",bg:"art/a1_west.webp",art:"[배경] 진료의자",gaze:{var:"steps",label:"발소리",look:7,mirror:5,tick:!0},idle:"진료의자 쪽이다. 아래에서 바람이 올라온다.",hotspots:[{id:"grate",label:"진료의자 아래 배수구",rect:[30,80,40,18],goto:"e2_grate"},{id:"chair",label:"진료의자",rect:[32,50,42,28],text:"의자 팔걸이의 가죽끈. 아까 이 의자에 앉았더라면.",textAgain:"생각하지 말자."},{id:"curtain_back",label:"커튼 뒷면",rect:[56,6,30,48],sfx:"rail",goto:"e2_north"}],mirror:{text:"거울을 바닥 쪽으로 기울인다. 진료의자 아래, 쇠창살 덮인 배수구가 비친다. 바람은 저기서 올라온다."},triggers:[{id:"caught",if:{gte:{steps:100}},goto:"e2_caught"}],choices:[{text:"수술대에 눕는다",kind:"ghost",if:{flag:{signed:!0}},goto:"e2_lie"},{text:"← 뒷방 문 쪽",kind:"ghost",goto:"e2_south",dir:"left"}],ambient:["바닥 아래에서 물 흐르는 소리.","…","천장에서 무언가 기어가는 소리."],viewClass:{"lamp-off":{gte:{steps:0}},vignette:{gte:{steps:0}}}},{id:"e2_grate",type:"event",title:"2막 · 배수구",bg:"art/e2_grate.webp",art:"[확대] 진료의자 아래 배수구",noMirror:!0,lines:["진료의자 아래, 바닥 배수구를 덮은 쇠창살. 작은 자물쇠가 달려 있다.","아래에서 축축한 바람이 올라온다."],choices:[{text:"맨손으로 당겨 본다",reply:"꿈쩍도 하지 않는다. 비틀 만한 도구가 필요하다."},{text:"물러선다",kind:"ghost",goto:"e2_west"}],use:{item_backkey:{text:[{text:"딸깍. 맞는다.",fx:"thud"},{who:"여자",text:"쥐한테 빚을 졌네."}],goto:"e2_pipe1"},item_scalpel:{effects:[{add:{steps:20}}],text:[{text:"끼이익— 금속 소리가 지하를 울린다.",fx:"thud"},"뒷방의 소리가 뚝 멎는다."],goto:"e2_pry"}},useWrong:"쇠창살은 그런 걸로 열리지 않는다."},{id:"e2_pry",type:"event",title:"2막 · 배수구",bg:"art/e2_grate.webp",art:"[확대] 비틀린 자물쇠",noMirror:!0,lines:["자물쇠가 비틀려 떨어진다."],choices:[{text:"배수구 아래로 내려간다",if:{lte:{steps:99}},goto:"e2_pipe1",dir:"down",dirLabel:"배수구 아래로"},{text:"…",if:{gte:{steps:100}},goto:"e2_caught"}]},{id:"e2_pipe1",type:"event",title:"2막 · 배관 통로",dark:!0,lines:["무릎 높이의 배관 통로. 오물 냄새가 목을 찌른다.",{who:"여자",text:"이 코트, 다시는 못 입겠네."},"첫 번째 갈림길. 왼쪽과 오른쪽."],choices:[{text:"거울로 모퉁이를 비춰 본다",if:{has:"item_mirror"},effects:[{add:{desire:1}}],reply:["거울을 모퉁이 너머로 내민다. 볼 때마다 자기 얼굴이 먼저 보인다. 번진 마스카라.","양쪽 다 어둡다. 어딘가에서 유리끼리 부딪치는 소리가 난다. 어느 쪽인지는 모르겠다."]}],hotspots:[{id:"in_left",label:"왼쪽 입구",rect:[14,30,30,56],glyph:"triangleDown",always:!0,goto:"e2_dead1",effects:[{add:{lost:1}},{fail:"pipes"}]},{id:"in_right",label:"오른쪽 입구",rect:[56,30,30,56],glyph:"triangle",always:!0,goto:"e2_vault"}]},{id:"e2_dead1",type:"event",title:"2막 · 하수",dark:!0,lines:["검은 물이 허리까지 차오른다. 물 위로 하얀 것들이 떠다닌다.","막다른 길이다. 뒤에서, 아주 멀리서 발소리."],choices:[{text:"되돌아간다",if:{lte:{lost:2}},goto:"e2_pipe1"},{text:"…",if:{gte:{lost:3}},goto:"e2_caught"}]},{id:"e2_vault",type:"room",title:"2막 · 수장고",bg:"art/e2_vault.webp",art:"[배경] 이름표 붙은 병이 늘어선 수장고",onFirst:[{meta:{know_vault:!0}}],intro:["통로 옆으로 난 작은 방. 선반마다 병이 늘어서 있다.","병마다 이름표가 붙어 있다. 사람 이름이다."],idle:"수장고다. 오래 머물 곳은 아니다.",hotspots:[{id:"costume",label:"무대 의상",rect:[6,4,40,28],text:["반짝이 장식이 달린 무대 의상이 옷걸이에 걸려 있다.","가슴께에 수놓인 이름. ‘Lena’.","신문 속 실종된 가수 L."],effects:[{add:{suspicion:1}}]},{id:"lamp",label:"광부 램프",rect:[6,36,40,28],text:"탄가루가 묻은 광부 램프. 손잡이에 새겨진 ‘M.’"},{id:"jars",label:"이름표 붙은 병",rect:[6,68,40,28],text:["이름표 붙은 병들. 병마다 마지막 날짜가 적혀 있다.","맨 끝의 병은 비어 있다. 이름표에는… 오늘 날짜."],effects:[{add:{suspicion:1}},{clue:"clue_vault_jar"}]},{id:"letters",label:"편지 묶음",rect:[52,70,44,26],text:["동의서 묶음과 함께 끈으로 묶인 편지들.","‘선생님, 정말 다시 볼 수 있는 거죠?’","맨 아래 편지 한 장은 잉크가 번져 반대쪽에 거꾸로 묻어 있다.",{who:"여자",text:"다들 똑같은 걸 물었네. 나만 안 물었고."}],mirror:["거울에 비춘 번진 글씨.","‘…쥐들이 다니는 길로 나왔어요. 바람이 들어오는 쪽으로요.’","누군가, 여기서 나간 적이 있다."],mirrorEffects:[{set:{letter_hint:!0}}]}],choices:[{text:"통로로 돌아간다",if:{seenCount:{prefix:"hs:e2_vault:",gte:2}},goto:"e2_valve"}],ambient:["병이 하나, 저절로 쨍 하고 운다.","옷걸이의 무대 의상이 흔들린다. 바람도 없는데.","…","멀리서 축음기 소리."]},{id:"e2_valve",type:"puzzle",kind:"rotate",title:"2막 · 무너진 배관",bg:"art/e2_vault.webp",art:"[배경] 배관",noMirror:!0,success:"e2_pipe2",exit:"e2_vault",stages:[{grid:["LIL","LIL","L.L"],rot:["311","000","000"],solution:["112","300","000"],from:[1,0,3],to:[1,2,1],hint:"valve1",tapsPerFail:10,water:1,prompt:"통로 앞 배관이 무너져 있다. 조각을 눌러 돌려, 왼쪽 입구에서 오른쪽 출구까지 물길을 잇는다.",done:"물이 졸졸 흐르기 시작한다.",after:["첫 번째 밸브가 풀린다."]},{grid:["LILL","LTIL","ILLL"],rot:["3011","1220","1231"],solution:["1120","3001","0003"],from:[1,0,3],to:[1,3,1],hint:"valve2",tapsPerFail:15,water:1,prompt:"다음 배관도 무너져 있다. 물길을 이어라.",done:"하수가 꾸르륵 빠져나간다.",after:["두 번째."]},{grid:[".LIII","ITLL.",".LI.L","L.LII"],rot:["03000","01220","00000","00011"],solution:["01111","10020","00000","00011"],from:[1,0,3],exits:[{to:[0,4,1],mark:"○",ok:!0},{to:[3,4,1],mark:"×"}],hint:"valve3",tapsPerFail:18,water:1,prompt:"마지막 배관. 출구가 둘이다. 물을 보낼 곳은 하나뿐이다.",done:"막혀 있던 통로가 드러난다.",blockedText:"물이 막힌다. 이쪽은 출구가 아니다."}]},{id:"e2_pipe2",type:"event",title:"2막 · 배관 통로",dark:!0,lines:["두 번째 갈림길. 세 갈래.",{text:"발치에서 찍찍 소리. 구석에 웅크려 있던 그 쥐다. 깜빡인다. 오른쪽 통로로 달려간다.",if:{flag:{rat_friend:!0}}},{text:"편지 속 문장이 떠오른다. 바람이 들어오는 쪽.",if:{flag:{letter_hint:!0}}}],choices:[{text:"거울로 모퉁이를 비춰 본다",if:{has:"item_mirror"},effects:[{add:{desire:1}}],reply:"세 갈래 모두 어둡다. 오른쪽에서만, 아주 약하게 찬바람이 분다."}],hotspots:[{id:"in_left",label:"왼쪽 입구",rect:[14,30,24,56],glyph:"ring",always:!0,goto:"e2_dead2",effects:[{add:{lost:1}},{fail:"pipes"}]},{id:"in_mid",label:"가운데 입구",rect:[38,30,24,56],glyph:"cross",always:!0,goto:"e2_dead2",effects:[{add:{lost:1}},{fail:"pipes"}]},{id:"in_right",label:"오른쪽 입구",rect:[62,30,24,56],glyph:"circle",always:!0,goto:"e2_hide"}]},{id:"e2_dead2",type:"event",title:"2막 · 막다른 길",dark:!0,lines:["벽이다. 손끝에 진득한 것이 묻는다.","발소리가 가까워진다."],choices:[{text:"되돌아간다",if:{lte:{lost:2}},goto:"e2_pipe2"},{text:"…",if:{gte:{lost:3}},goto:"e2_caught"}]},{id:"e2_hide",type:"event",title:"2막 · 숨바꼭질",bg:"art/e2_hide.webp",art:"[수술] 어둠 속에서 내려다보는 닥터",noMirror:!0,lines:["통로가 넓어지는 곳에서, 앞쪽 사다리 근처에 불빛이 흔들린다.","닥터다. 먼저 와 있었다.",{who:"닥터",text:"하나, 둘, 셋… 크크. 하나가 모자라."},"여자는 배관 뒤에 몸을 붙인다.","멀리 진료실에서, 축음기 「달빛」이 흐르기 시작한다. 닥터가 틀어 놓고 나온 것이다.","곡이 끝나 바늘이 헛돌면, 닥터는 판을 갈러 돌아갈 것이다. 그 순간을 노려야 한다.",{text:"메모가 떠오른다. 「달빛」, 4분 10초.",if:{has:"item_record_memo"}},{text:"「달빛」은 꽤 긴 곡이다. 언제 움직일까.",if:{not:{has:"item_record_memo"}}}],choices:[{text:"때를 잰다",goto:"e2_hide_dial"}]},{id:"e2_hide_dial",type:"puzzle",kind:"dial",title:"2막 · 숨바꼭질",bg:"art/e2_hide.webp",art:"[수술] 어둠 속에서 내려다보는 닥터",noMirror:!0,label:"「달빛」",max:270,prompt:"축음기 바늘이 돈다. 곡이 끝나기 직전, 닥터는 판을 갈러 몸을 돌린다. 그 순간에 누른다.",confirm:"지금 움직인다",live:!0,secPerMin:5,maxFails:3,hint:"dial",bands:[{max:115,fail:!0,effects:[{add:{trust:-2}}],reply:"곡은 아직 한창이다. 조용한 대목에서, 발소리가 너무 또렷하다. 닥터가 고개를 돌린다.",retryText:"발끝이 배관을 스친다. 닥터가 이쪽을 한참 본다. …다시 몸을 붙인다. 닥터가 바늘을 처음으로 되돌린다.",goto:"e2_caught"},{max:241,fail:!0,effects:[{add:{trust:-2}}],reply:"소리에 섞여 나갈 수 있을 줄 알았다. 닥터는 소리가 아니라 그림자를 보고 있었다.",retryText:"그림자가 흔들린다. 닥터가 고개를 갸웃한다. …아직이다. 다시 숨는다. 바늘이 처음으로 돌아간다.",goto:"e2_caught"},{max:250,reply:"마지막 음이 꺼지기 직전. 닥터가 판을 갈러 몸을 돌린다. 지금이다.",goto:"e2_slip"},{max:99999,fail:!0,effects:[{add:{trust:-2}}],reply:"너무 늦었다. 판을 갈고 돌아오는 닥터와, 사다리 앞에서 마주친다.",retryText:"너무 늦었다. 닥터가 벌써 판을 갈고 돌아선다. …다행히 이쪽은 보지 않았다. 「달빛」이 처음부터 다시 흐른다.",goto:"e2_caught"}],exit:"e2_hide",retryFrom:210},{id:"e2_slip",type:"event",title:"2막 · 숨바꼭질",bg:"art/e2_exit.webp",art:"[배경] 통로 끝 불빛",noMirror:!0,lines:["곡의 마지막 음이 길게 늘어진다. 바늘이 헛돈다.",{who:"닥터",text:"…쯧. 판 갈아야지."},"닥터가 돌아서는 순간, 여자는 사다리로 뛴다.","위쪽 맨홀 틈으로 빗소리가 들린다."],choices:[{text:"사다리를 오른다",goto:"e2_street",dir:"up",dirLabel:"사다리 위로"}]},{id:"e2_street",type:"event",title:"3막 · 빗속",bg:"art/p2_patrol.webp",art:"[배경] 빗속 골목",fx:["heavyrain"],noMirror:!0,lines:["맨홀 뚜껑을 밀어 올리자, 통금이 내린 빗속 골목.","숨을 고를 새도 없이 손전등 불빛. 순찰병이다."],choices:[{text:"배급표를 내민다",if:{has:"item_ration"},effects:[{take:"item_ration"}],reply:[{who:"순찰병",text:"…또 당신이군. 이 골목은 밤마다 사람이 줄어든다니까."},"순찰병은 오물 범벅인 여자를 위아래로 훑더니, 길을 비킨다."],goto:"e2_puddle"},{text:"그대로 달린다",reply:"등 뒤로 호루라기 소리. 여자는 골목 몇 개를 뛰어 넘는다. 구두 굽이 부러진다.",goto:"e2_puddle"}]},{id:"e2_puddle",type:"event",title:"3막 · 웅덩이",bg:"art/p1_bag.webp",art:"[S1-2] 빗속의 여자",fx:["rain"],noMirror:!0,lines:["숨을 고르다, 발밑 웅덩이를 내려다본다.","빗물에 비친 얼굴. 진흙, 오물, 번진 마스카라.",{who:"여자",text:"이 얼굴 하나 지키자고 지하까지 기어 내려갔다 올라왔네."},"그런데 이상하다. 웅덩이 속 얼굴이 자꾸만 초라해 보인다."],choices:[{text:"웅덩이를 밟고 떠난다",goto:"end_return_leave"},{text:"다음 날 밤, 다시 초인종을 누른다",goto:"e2_return"}]},{id:"e2_return",type:"event",title:"다음 날 밤",bg:"art/end_return.webp",art:"[등장] 다시 철문 앞의 여자",noMirror:!0,fx:["rain"],onEnter:[{set:{route:"surgery",returned:!0,signed:!0}},{add:{desire:1}}],lines:["다음 날 밤. 같은 골목, 같은 계단, 같은 철문.",{text:"짧게, 길게, 짧게, 짧게, 길게, 짧게.",fx:"thud"},"철컥. 문구멍이 열린다. 둥근 눈이 깜빡이지 않는다.",{who:"닥터",text:"…다시 왔군. 크크. 그럴 줄 알았지."},{who:"여자",text:"어제 일은 없던 걸로 해요. 오늘은 서명할 테니까.",if:{not:{flag:{signed:!0}}}},{who:"여자",text:"어제 그 서명, 아직 유효하죠?",if:{flag:{signed:!0}}}],choices:[{text:"…",goto:"s2_table"}]},{id:"end_return_leave",type:"ending",ending:"return",title:"빗속의 귀환",bg:"art/end_return.webp",art:"[등장] 빗속의 여자",fx:["rain"],lines:["여자는 웅덩이를 밟고 지나간다. 비친 얼굴이 산산이 흩어진다.",{who:"여자",text:"됐어. 이 정도면 충분히 예뻐."},"…그 말이 진심인지는, 내일 아침 거울을 보기 전까지 모른다."]},{id:"e2_caught",type:"event",title:"2막 · 붙잡힘",bg:"art/e2_caught.webp",art:"[등장] 코앞의 둥근 눈",noMirror:!0,onEnter:[{if:{not:{flag:{signed:!0}}},add:{trust:-10}},{if:{flag:{signed:!0}},add:{trust:-3}},{set:{route:"surgery",caught:!0}}],lines:["등 뒤에서 곰방대 냄새.",{who:"닥터",text:"찾았다."},"둥근 눈이 코앞에 있다. 깜빡이지 않는다.",{who:"닥터",text:"손님이 계약서를 안 쓰면, 계약서가 손님을 쓰는 법이지. 크크.",if:{not:{flag:{signed:!0}}}},{who:"닥터",text:"서명까지 해 놓고 도망을? 크크. 계약서는 거짓말을 안 하는데.",if:{flag:{signed:!0}}},{who:"여자",text:"…손님 대접이 아주 극진하네."}],choices:[{text:"…",goto:"s2_table"}]}],wt=[{id:"p1_stop",type:"event",title:"프롤로그 · 정류장",art:"[이벤트 컷] 막차가 떠난 정류장, 가로등 아래 젖은 모자의 여자",fx:["rain"],lines:["전쟁이 몇 번째 겨울을 맞았는지, 이제 아무도 세지 않는다.","막차가 떠난 정류장. 가로등 하나가 젖은 돌바닥을 핥고 있다.","여자는 모자챙에서 떨어지는 빗물을 털지 않았다. 젖은 모자도 나름 그림이 된다고 생각했으니까.",{who:"여자",text:"주소 대신 수수께끼라. 불법 시술소답게 촌스럽네."},{text:"가로등 아래 웅덩이에, 일곱 개의 반짝임이 떠 있다. 깜빡이지 않는다.",if:{meta:"all_eyes"}}],choices:[{text:"핸드백을 연다",goto:"p1_bag"}],bg:"art/p1_stop.webp"},{id:"p1_bag",type:"event",title:"프롤로그 · 정류장",art:"[확대] 열린 핸드백 — 손거울, 금화, 배급표, 쪽지",fx:["rain"],onFirst:[{give:"item_mirror"},{give:"item_coins"},{give:"item_ration"},{give:"item_note"},{clue:"hint_note_back"},{give:"item_telegram"},{clue:"hint_telegram"}],lines:["핸드백 안에는 손거울, 금화 세 닢, 배급표, 구겨진 쪽지. 그리고 접힌 전보 한 장.",'쪽지 앞면 — "두더지는 땅 밑에 산다."',`뒷면에는 점과 선이 그려져 있다. 빗물에 번져 뒤의 네 칸은 읽을 수 없다.

·  —  ?  ?  ?  ?`,"전보 — ‘주연 교체. 사유: 카메라가 눈을 잡지 못함.’",{who:"여자",text:"못 잡는 건 카메라 쪽이겠지."},"손거울 속 눈을 들여다본다. 화면 속 눈은 늘 빛났다. 거울 속 눈은 아무것도 붙잡지 않는다.",{text:"손거울을 열어 본다. …이번엔 끝까지 볼까.",if:{any:[{ending:"liberation"},{ending:"truth"}]}}],mirror:{text:"가로등 아래 젖은 얼굴. 마스카라는 번지지 않았다. …다행이다. 이 얼굴이 재산이니까."},choices:[{text:"골목으로 들어간다",goto:"p2_alley"}],bg:"art/p1_bag.webp"},{id:"p2_alley",type:"room",title:"프롤로그 · 통금 골목",art:"[배경] 간판을 떼어낸 가게들이 늘어선 골목, 끝은 벽돌 벽",fx:["rain"],intro:["통금이 가까운 골목. 간판을 떼어낸 가게들이 줄지어 서 있다.","'땅 밑'이라고 했다. 어딘가 아래로 내려가는 곳이 있을 것이다.","빗소리 너머 어딘가, 군화 소리가 일정하게 오간다."],idle:"어딘가 아래로 내려가는 곳이 있을 것이다. 살펴볼 곳을 누르세요.",hotspots:[{id:"window",label:"가게 창문",rect:[40,20,40,40],text:["먼지 낀 유리 너머로 마네킹 머리들이 줄지어 있다.","얼굴마다 두 군데가 비어 있다. 매끈하게."],textAgain:"마네킹들은 여전히 이쪽을 향해 있다. 볼 것도 없으면서.",effects:[{add:{suspicion:1}}]},{id:"poster",label:"벽보",rect:[4,14,26,34],text:["'통금 22시. 위반자는 즉시 연행.'","그 아래 누군가 연필로 휘갈겨 썼다. '보는 눈이 많다.'","벽보 귀퉁이가 들떠 있다. 젖은 종이 너머로 뒷면의 무언가가 비친다. 거꾸로다."],textAgain:"'보는 눈이 많다.'",mirror:["거울에 비친 벽보 뒷면.","손톱으로 눌러 새긴 기호. ?  ?  ?  ?  —  ·"],mirrorEffects:[{clue:"hint_poster"}]},{id:"drain",label:"배수구",rect:[6,80,40,16],text:["빗물이 배수구로 빨려 들어간다.","물 떨어지는 소리가 이상하게 길다. 훨씬 아래에 넓은 공간이 있다.","창살 하나가 녹슬어 빠져 있다. 여자는 그것을 집어 든다. 쇠막대다.","녹슨 창살이 빠지며, 쨍— 소리가 젖은 벽을 타고 올라간다.",{text:"오가던 군화 소리가 뚝 멎는다.",if:{all:[{lte:{noise:1}},{not:{flag:{patrolled:!0}}}]}}],textAgain:"물소리가 땅 밑 깊은 곳까지 이어진다.",effects:[{give:"item_bar"},{add:{noise:1}},{set:{last_noise:"clang"},if:{not:{flag:{patrolled:!0}}}}]},{id:"end",label:"골목 끝",rect:[82,18,16,52],text:"골목 끝은 벽돌 벽으로 막혀 있다. 젖은 벽돌뿐이다.",textAgain:"막힌 벽. …정말 막혀 있을까?"},{id:"plank",label:"벽 아래 판자",rect:[60,80,36,18],if:{all:[{any:[{seen:"hs:p2_alley:drain"},{clue:"hint_light"}]},{not:{flag:{plank_open:!0}}}]},text:["벽 아래, 판자로 막힌 구멍. 판자 틈으로 빗물이 빨려 들어간다.","틈 너머로 계단이 보인다. 판자는 못으로 박혀 있다."],use:{item_bar:{text:["쇠막대를 판자 틈에 끼우고 힘을 준다.",{text:"끼이익— 못이 뽑혀 나간다.",fx:"thud"}],effects:[{set:{plank_open:!0}},{set:{last_noise:"plank"},if:{not:{flag:{patrolled:!0}}}},{goto:"p2_patrol",if:{not:{flag:{patrolled:!0}}}}],goto:"p3_descend"}},useHint:"틈에 끼워 비틀 만한 것이 필요하다. 배수구 쪽에 무언가 있었다."},{id:"stairs",label:"벽 아래 계단",rect:[60,80,36,18],if:{flag:{plank_open:!0}},goto:"p3_descend"},{id:"eye",label:"반짝이는 것",rect:[0,86,10,12],hidden:!0,once:!0,text:"웅덩이 바닥에서 무언가 하늘을 올려다보고 있다.",eye:"eye_puddle"}],mirror:{if:{not:{flag:{flashed:!0}}},effects:[{set:{flashed:!0}},{add:{noise:1}},{set:{last_noise:"flash"},if:{not:{flag:{patrolled:!0}}}}],text:["가로등 불빛이 거울에 맞아, 맞은편 벽에 하얗게 튄다. 한 번.",{text:"오가던 군화 소리가 뚝 멎는다.",if:{all:[{lte:{noise:1}},{not:{flag:{patrolled:!0}}}]}}]},triggers:[{id:"patrol",if:{all:[{gte:{noise:2}},{not:{flag:{patrolled:!0}}}]},goto:"p2_patrol"}],bg:"art/p2_alley.webp",ambient:["멀리서 호루라기.","빗물이 배수구로 빨려 든다.","창문 너머, 마네킹 하나가 고개를 돌린 것 같다.","…"]},{id:"p2_patrol",type:"event",title:"프롤로그 · 통금 골목",art:"[이벤트 컷] 골목 입구에서 흔들리는 손전등 불빛, 군화",fx:["rain"],noMirror:!0,lines:[{text:"쇳소리가 아직 골목 끝에서 맴돌고 있다.",if:{flag:{last_noise:"clang"}}},{text:"벽에 튄 빛을 따라, 손전등 불빛 하나가 골목으로 꺾여 들어온다.",if:{flag:{last_noise:"flash"}}},{text:"못 빠지는 소리가 빗소리를 찢고 골목 밖까지 나간다.",if:{flag:{last_noise:"plank"}}},{text:"저벅. 저벅.",fx:"thud"},"골목 입구에서 손전등 불빛이 흔들린다. 순찰병이다.","이 시간에 혼자 걷는 여자를, 그냥 보내줄 리 없다."],choices:[{text:"쓰레기통 뒤로 숨는다",reply:["썩은 양배추 냄새. 숨을 참는다.","불빛이 코앞의 웅덩이를 지나간다… 그리고 멀어진다.",{text:"판자는 반쯤 뜯겨 있다. 계단이 보인다.",if:{flag:{last_noise:"plank"}}}],goto:"p2_alley"},{text:"처마 밑에 선다. 당당하게.",effects:[{add:{desire:1}}],goto:"p2_caught"},{text:"모자를 깊게 눌러쓰고 걸어간다",goto:"p2_caught"}],bg:"art/p2_patrol.webp",onEnter:[{set:{patrolled:!0}}]},{id:"p2_caught",type:"event",title:"프롤로그 · 통금 골목",art:"[이벤트 컷] 손전등에 비친 여자의 얼굴, 그림자 진 순찰병",fx:["rain"],noMirror:!0,lines:[{who:"순찰병",text:"이 시간에 혼자? 신분증."},"손전등 불빛이 여자의 얼굴 위에 오래 머문다. 너무 오래.","무언가 내밀어야 한다."],choices:[],bg:"art/p2_caught.webp",use:{item_coins:{if:{gte:{coins:1}},effects:[{add:{coins:-1}}],text:["순찰병은 금화를 이로 깨물어 보더니, 못 본 척 등을 돌린다.",{who:"여자",text:"정의도 금화 한 닢이면 등을 돌리지."},{text:"판자는 반쯤 뜯겨 있다. 계단이 보인다.",if:{flag:{last_noise:"plank"}}}],goto:"p2_alley",failText:"금화가 남아 있지 않다."},item_ration:{effects:[{add:{suspicion:1}}],text:["순찰병은 배급표를 한참 들여다보다가, 여자의 얼굴과 번갈아 본다.",{who:"순찰병",text:"…빨리 들어가시오. 이 골목엔 밤마다 사람이 줄어드니까."},{text:"판자는 반쯤 뜯겨 있다. 계단이 보인다.",if:{flag:{last_noise:"plank"}}}],goto:"p2_alley"},item_mirror:{text:[{who:"순찰병",text:"…거울 말고, 신분증."}]},item_note:{text:["쪽지를 내밀려다 멈춘다. 두더지 이야기를 순찰병에게 할 수는 없다."]}},useWrong:[{who:"순찰병",text:"그게 뭐요. 장난하오?"}]},{id:"p3_descend",type:"event",title:"프롤로그 · 지하 계단",bg:"art/p3_descend.webp",art:"[이벤트 컷] 지하로 내려가는 계단",fx:["rain"],noMirror:!0,lines:["막힌 벽 바로 아래, 바닥보다 낮게 꺾여 내려가는 좁은 계단.","빗물이 폭포처럼 흘러내린다. 여자는 치맛자락을 쥐고 한 칸씩 내려간다."],choices:[{text:"내려간다",goto:"p3_stairs"}]},{id:"p3_stairs",type:"room",title:"프롤로그 · 지하 계단",art:"[배경] 빗물이 빨려드는 계단 끝, 녹슨 철문과 초인종",fx:["heavyrain"],intro:["계단 끝, 녹슨 철문.","문 한가운데 눈높이에 작은 구멍. 그 옆에 초인종 하나."],idle:"철문 앞이다. 살펴볼 곳을 누르세요.",hotspots:[{id:"door",label:"철문",rect:[30,6,44,44],text:"두드려 봐도 소리가 빗소리에 묻힌다. 안쪽은 조용하다. 너무 조용하다."},{id:"frame",label:"문틀",rect:[78,8,16,56],text:["문틀 나무에 손톱으로 새긴 자국이 있다.","?  ?  ·  ·  ?  ?","앞뒤는 누군가 일부러 긁어서 지웠다.","쪽지 뒷면의 기호와 닮았다."],textAgain:"문틀의 자국. ?  ?  ·  ·  ?  ?",effects:[{clue:"hint_frame"}]},{id:"bell",label:"초인종",rect:[6,40,16,16],goto:"p3_bell"},{id:"eye",label:"반짝이는 것",rect:[86,86,12,12],hidden:!0,once:!0,text:"계단 모서리 틈에 동그란 것이 끼어 있다.",eye:"eye_step"}],mirror:{text:"손거울을 들어 문구멍에 비춰 본다. 반사된 구멍 안쪽에서 — 무언가가 깜빡이지 않고 이쪽을 보고 있다.",effects:[{clue:"hint_peephole"},{add:{suspicion:1}}]},choices:[{text:"쪽지 뒷면을 다시 본다",if:{has:"item_note"},kind:"ghost",reply:`쪽지 뒷면.

·  —  ?  ?  ?  ?

뒤의 네 칸은 번져서 읽을 수 없다.`},{text:"계단을 다시 올라간다",kind:"ghost",goto:"p2_alley",dir:"up",dirLabel:"골목으로"}],bg:"art/p3_stairs.webp",ambient:["철문 안쪽에서 무언가 끌리는 소리.","빗물이 계단을 타고 흘러내린다.","…","문구멍 덮개가 아주 조금 흔들린다."]},{id:"p3_bell",type:"puzzle",kind:"rhythm",title:"프롤로그 · 초인종",art:"[S1-1 확대] 철문",fx:["heavyrain"],noMirror:!0,answer:".-..-.",prompt:"아무렇게나 누르면 열리지 않을 것이다. 정해진 리듬이 있다.",wrong:"…응답이 없다. 빗소리만 들린다.",maxFails:6,success:"p4_peep",successEffects:[{meta:{know_rhythm:!0}},{set:{bell_ok:!0}}],fail:"p3_angry",failEffects:[{add:{trust:-2}}],choices:[{text:"기억하는 리듬으로 누른다",if:{meta:"know_rhythm"},goto:"p4_peep"}],bg:"art/p3_bell.webp",hint:"bell",exit:"p3_stairs"},{id:"p3_angry",type:"event",title:"프롤로그 · 지하 계단",art:"[이벤트 컷] 철문 너머로 끌리는 쇠붙이 그림자",fx:["heavyrain"],noMirror:!0,lines:[{text:"여섯 번째 초인종이 울리자, 문 너머에서 쇠붙이 끄는 소리가 난다.",fx:"thud"},{who:"문 너머의 목소리",text:"…시끄럽군. 동네 사람 다 깨우겠어."},{who:"문 너머의 목소리",text:"들어와. 다음엔 제대로 눌러. 다음이 있다면."}],choices:[{text:"…",goto:"p4_peep"}],bg:"art/p3_angry.webp"},{id:"p4_peep",type:"event",title:"프롤로그 · 문구멍",art:"[이벤트 컷] 문구멍 너머의 눈 — 둥글고, 깜빡이지 않는다",fx:["heavyrain"],noMirror:!0,lines:[{text:"철컥. 문구멍의 덮개가 열린다.",fx:"thud"},"구멍 너머로 눈 하나. 둥글고, 크고, 눈꺼풀이 없는 것처럼 깜빡이지 않는다.",{who:"문 너머의 목소리",text:"누가 보냈지?"}],choices:[{text:"다시 왔어요.",if:{meta:"know_rhythm"},effects:[{add:{trust:1}}],reply:{who:"문 너머의 목소리",text:"…그 얼굴. 어디선가 본 것 같군."},goto:"p4_q2"},{text:"극장 분장사요. 당신 얘기를 하더군요.",effects:[{add:{trust:1}}],reply:{who:"문 너머의 목소리",text:"그 수다쟁이. 손재주는 없어도 입은 가볍지."},goto:"p4_q2"},{text:"아무도요. 소문을 듣고 왔어요.",reply:{who:"문 너머의 목소리",text:"소문이라. 소문은 늘 반쯤 틀리지."},goto:"p4_q2"},{text:"(말없이 쪽지를 내민다)",effects:[{add:{trust:-1,suspicion:1}}],reply:["눈이 쪽지를 훑는다. 한참.",{who:"문 너머의 목소리",text:"…두더지라. 촌스러운 별명이군."}],goto:"p4_q2"}],bg:"art/p4_peep.webp"},{id:"p4_q2",type:"event",title:"프롤로그 · 문구멍",art:"[이벤트 컷] 문구멍 너머의 눈",fx:["heavyrain"],noMirror:!0,lines:[{who:"문 너머의 목소리",text:"무엇을 원하지?"}],choices:[{text:"새 눈이요.",effects:[{add:{desire:1}}],goto:"p4_q3"},{text:"더 아름다워지고 싶어요.",effects:[{add:{desire:2}}],reply:{who:"문 너머의 목소리",text:"크크. 다들 그렇게 말하지. 처음엔."},goto:"p4_q3"},{text:"당신 실력이 소문만큼인지 확인하러요.",effects:[{add:{suspicion:1,trust:-1}}],reply:{who:"문 너머의 목소리",text:"확인이라. …좋아. 증명은 내 전문이니까."},goto:"p4_q3"}],bg:"art/p4_peep.webp"},{id:"p4_q3",type:"event",title:"프롤로그 · 문구멍",art:"[S1-4] 바스트 투샷 — 노려보는 닥터와 도도한 여자",fx:["heavyrain"],noMirror:!0,lines:[{who:"문 너머의 목소리",text:"얼굴을 보여줘."},"선글라스가 아직 콧등에 걸려 있다."],choices:[{text:"선글라스를 벗는다",effects:[{add:{desire:1,trust:1}},{set:{face_hidden:!1}}],reply:"눈이 여자의 얼굴을 위아래로 훑는다. 오래. 아주 오래.",goto:"p4_open"},{text:"그대로 둔다",effects:[{add:{suspicion:1}},{set:{face_hidden:!0}}],reply:{who:"문 너머의 목소리",text:"…신중하군. 상관없어. 어차피 안에서는 다 벗게 되니까."},goto:"p4_open"}],bg:"art/p4_peep.webp"},{id:"p4_open",type:"event",title:"프롤로그 · 문이 열린다",art:"[이벤트 컷] 열린 철문, 눈이 아플 만큼 하얀 빛",noMirror:!0,lines:[{text:"빗장이 하나, 둘, 셋 풀린다.",fx:"thud"},{text:"문이 열리자 — 눈이 아플 만큼 하얀 빛.",fx:"flash"},{who:"닥터",text:"어서 와. 젖은 건 거기 두고.",if:{gte:{trust:1}}},{who:"닥터",text:"들어와. 물 떨어뜨리지 말고.",if:{lte:{trust:0}}}],choices:[{text:"안으로 들어간다",goto:"p4_enter"}],bg:"art/p4_open.webp"},{id:"p4_enter",type:"event",title:"프롤로그 · 문턱",bg:"art/p4_enter.webp",art:"[S1-5] 문 안으로 들어가는 발걸음, 뒤로 떨어지는 검은 물",noMirror:!0,titleCard:!0,lines:["여자가 문턱을 넘는다.","그 뒤로 검은 물이 뚝, 뚝 떨어진다."],choices:[{text:"…",goto:"a1_meet"}]}],kt=[{id:"s2_table",type:"event",title:"2막 · 수술대",bg:"art/s2_table.webp",art:"[S4-2] 누운 여자가 올려다본 닥터",noMirror:!0,lines:[{text:"다음 날 밤. 같은 수술대, 같은 천장.",if:{flag:{returned:!0}}},{text:"끌려온 수술대. 붕대가 손목을 파고든다.",if:{flag:{caught:!0}}},"수술대에 눕는다. 얼굴과 몸통이 붕대로 감겨 움직일 수 없다.","누워 있으니, 점점 불안해진다.",{text:"수장고에서 본 빈 병이 수술대 옆 쟁반 위에 와 있다. 여자는 이름표를 보지 않기로 한다.",if:{clue:"clue_vault_jar"}},"닥터가 축음기에 판을 올린다. 클래식이 흐르고, 닥터가 음에 맞춰 흥얼거린다.","닥터가 여자의 눈꺼풀을 감지 못하게 고정한다. 면봉에 묻힌 검은 진액이 눈가에 닿는다.",{who:"닥터",text:"다시 태어나는 거야. 가만히 있어."},"[안내] 마취되기 전에, 노트에서 무엇을 기억에 새길지 정하세요. 마취 후에는 바꿀 수 없습니다."],choices:[{text:"입꼬리를 들어 웃는다",effects:[{add:{desire:1}}],reply:"포박된 채로, 여자는 웃는다.",goto:"s2_blur"},{text:"몸을 비틀어 본다",effects:[{add:{suspicion:1}}],reply:"붕대는 꿈쩍도 하지 않는다.",goto:"s2_blur"}]},{id:"s2_blur",type:"event",title:"2막 · 마취",bg:"art/s2_blur.webp",art:"[수술] 흐려지는 시야 속 닥터",noMirror:!0,lines:["마취 주사기가 몸으로 들어온다. 시야가 서서히 흐려진다.","음악과, 흥얼거림과, 의료 기구가 달그락거리는 소리가 점점 커지다가—",{text:"뚝.",fx:"thud"}],choices:[{text:"…",goto:"s2_doc_mirror"}],onEnter:[{set:{mem_locked:!0}}]},{id:"s2_doc_mirror",type:"event",title:"2막 · 닥터",bg:"art/s2_prep.webp",art:"[수술] 수술을 준비하는 닥터",pov:"doctor",lines:["조용하군. 이제야 일할 맛이 나지.",{who:"닥터",text:"말 자르던 입이 조용하니 좋군.",if:{gte:{cut:2}}},{who:"닥터",text:"끝까지 듣던 손님이야. …손이 가볍군.",if:{all:[{not:{gte:{cut:2}}},{gte:{trust:1}}]}},{who:"닥터",text:"의심 많은 눈이었어. 감겨 놓으니 별거 없군.",if:{all:[{not:{gte:{cut:2}}},{not:{gte:{trust:1}}},{lte:{trust:-1}}]}},{who:"닥터",text:"거울을 그렇게 들여다보더니.",if:{all:[{not:{gte:{cut:2}}},{not:{gte:{trust:1}}},{not:{lte:{trust:-1}}},{gte:{desire:5}}]}},"가운 주머니에서 무언가 떨어진다. 손거울. 여자의 것이다."],choices:[{text:"치운다",effects:[{set:{mirror_left:!1}}],reply:"수술대 위에 거울은 필요 없다.",goto:"s2_serum"},{text:"그대로 둔다",effects:[{set:{mirror_left:!0}}],reply:"깨어나면 제일 먼저 찾을 테니. 크크.",goto:"s2_serum"}]},{id:"s2_serum",type:"event",title:"2막 · 진액",bg:"art/s2_prep.webp",art:"[수술] 진액 통",pov:"doctor",lines:["진액 통을 연다.",{text:"…뚜껑이 이미 열려 있다. 누가 열었지? 표면이 굳어 꺼끌하다.",if:{flag:{serum_open:!0}}},"바닥이 보인다. 거의 비었다.","닥터가 천장을 올려다본다. 틈 사이로 검은 것이 실처럼 늘어져 있다.",{who:"닥터",text:"크크. 직접 받지. 세 방울이면 꿀처럼 늘어지고."}],choices:[{text:"…",goto:"s2_eye"}]},{id:"s2_eye",type:"event",title:"2막 · 눈",bg:"art/s2_eye.webp",art:"[수술] 아래에서 올려다본 닥터의 웃음",pov:"doctor",lines:["이제 넣을 눈을 고를 차례.",{text:"약속한 건 금귤빛 홍채.",if:{flag:{eye_choice:"gold"}}},{text:"약속한 건 견본 L. 푸른 눈.",if:{flag:{eye_choice:"blue"}}},{text:"나에게 맡겼지. 크크. 현명한 손님이야.",if:{flag:{eye_choice:"doctor"}}},{text:"…그런데 이 손님, 내 물건을 너무 많이 만졌다.",if:{lte:{trust:-1}}}],choices:[{text:"약속한 눈을 넣는다",goto:"s2_scale"},{text:"내 최신작을 넣는다",effects:[{set:{final_eye:"experiment"}}],reply:"아직 사람에게 써 본 적은 없지만. 증명은 언제나 처음이 있는 법.",goto:"s2_operate"},{text:"아무것도 넣지 않는다",effects:[{set:{final_eye:"none"}}],reply:"이 눈은 선반에 둔다. 마지막 이름표가 비어 있었으니까.",goto:"s2_operate"}]},{id:"s2_scale",type:"puzzle",kind:"scale",title:"2막 · 저울",bg:"art/s2_prep.webp",art:"[수술] 저울과 병",pov:"doctor",weights:[3,1,4,2],labels:["ㄱ","ㄴ","ㄷ","ㄹ"],answer:0,maxWeigh:4,failAt:3,hint:"scale",prompt:"이름표가 녹아 지워진 병 넷. 수술 메모 귀퉁이에 한 줄. ‘약속한 것 — 둘째로 무겁다.’ 병 두 개를 골라 저울에 올린다. 네 번까지.",pickPrompt:"어느 병이지.",successEffects:[{set:{final_eye:"promised"}}],success:"s2_operate",failEffects:[{set:{final_eye:"mixed"}}],failText:"손에 쥔 무게가 어쩐지 낯설다. …이미 늦었다.",fail:"s2_operate"},{id:"s2_operate",type:"puzzle",kind:"surgery",title:"2막 · 이식",bg:"art/s2_operate.webp",art:"[수술] 메스를 든 닥터",pov:"doctor",success:"s2_incident"},{id:"s2_incident",type:"event",title:"2막 · 돌발",bg:"art/s2_incident.webp",art:"[S4-1] 수술대",pov:"doctor",sound:{heart:.85},lines:[{text:"봉합을 마치려는 순간—",sfx:"sting"},{text:"손끝이 아직 떨린다. 실수가 너무 많았다.",if:{gte:{op_miss:3}}},{text:"발치에서 무언가 기어 온다. 뚜껑이 열린 진액 통에서 빠져나온 구더기들이 수술대 다리를 타고 오른다.",if:{flag:{serum_open:!0}}},{text:"수술 메모를 펼친다. 젖은 모자에서 번진 빗물에 순서가 흐려져 있다. 마지막 줄이 읽히지 않는다.",if:{all:[{not:{flag:{serum_open:!0}}},{flag:{hat_place:"desk"}}]}},{text:"천장에서 진액 한 방울이 떨어진다. 하필이면 막 봉합한 자리 위로.",if:{all:[{not:{flag:{serum_open:!0}}},{not:{flag:{hat_place:"desk"}}},{not:{clue:"clue_ceiling"}}]}},{text:"멈췄던 축음기가 저절로 다시 돌기 시작한다. 손님은 마취 중이다. 그렇다면 누가?",if:{all:[{not:{flag:{serum_open:!0}}},{not:{flag:{hat_place:"desk"}}},{clue:"clue_ceiling"}]}}],choices:[{text:"침착하게 수습한다",effects:[{set:{incident_ok:!0}}],reply:"숨을 고른다. 곰방대를 문다. 천천히, 하나씩.",goto:"s2_dream"},{text:"서둘러 끝낸다",effects:[{set:{incident_ok:!1}}],reply:"어차피 결과는 같다. 매듭을 대충 묶는다.",goto:"s2_dream"}]},{id:"s2_dream",type:"event",title:"꿈",bg:"art/s2_dream.webp",art:"[S5] 나비가 되어 날아가는 구더기",noMirror:!0,onEnter:[{set:{surgery_result:"blind"}},{set:{surgery_result:"success"},if:{all:[{flag:{final_eye:"promised"}},{flag:{serum:"normal"}},{flag:{incident_ok:!0}},{gte:{desire:6}},{lte:{op_miss:2}}]}},{set:{surgery_result:"removed"},if:{flag:{final_eye:"none"}}}],lines:["붕대에 감긴 구더기 한 마리.","붕대가 한 겹씩 풀리고, 등에서 날개가 돋는다.","나비가 되어, 빛 쪽으로 날아간다.","처음으로 아무도 쳐다보지 않는다. 처음으로 아무것도 쳐다보지 않는다."],choices:[{text:"눈을 뜬다",if:{flag:{surgery_result:"blind"}},goto:"s3_wait"},{text:"눈을 뜬다",if:{flag:{surgery_result:"success"}},goto:"s3_gold_wake"},{text:"눈을 뜬다",if:{flag:{surgery_result:"removed"}},goto:"s3_removed_wake"}]},{id:"s3_wait",type:"event",title:"3막 · 시술 후",bg:"art/s3_wait.webp",art:"[S6-1] 차를 마시며 신문을 보는 닥터",pov:"doctor",lines:["시술이 끝났다. 차를 홀짝인다.","신문 낱말 맞추기. 세로 열쇠 3번, ‘눈을 감아야 보이는 것’. 한 글자.","‘꿈’이라고 적는다. 크크.","신문 너머로 수술대 위 여자가 보인다. 시체처럼 뻗어 있다."],choices:[{text:"…",goto:"s3_stir"}]},{id:"s3_stir",type:"event",title:"3막 · 시술 후",bg:"art/s3_stir.webp",art:"[S6-3] 꿈틀거리는 여자",pov:"doctor",lines:["여자의 몸이 조금씩 꿈틀거린다.","지루함이 끝났다는 듯, 신문을 내려놓는다.",{who:"닥터",text:"오! 깨어났군! 깨어났어!"}],choices:[{text:"…",goto:"s3_dark"}]},{id:"s3_dark",type:"event",title:"3막 · 어둠",dark:!0,lines:["어둡다.","눈을 떴다. 분명히 떴다. 그런데 어둡다.","붕대 냄새. 진액 냄새. 욱신거린다.",{who:"여자",text:"아… 아아…"},"볼 수 없다. 새겨 둔 것만 남아 있다."],choices:[{text:"새겨 둔 기억을 더듬는다",goto:"s3_q_license"}]},{id:"s3_q_license",type:"event",title:"3막 · 기억",dark:!0,onEnter:[{goto:"s3_q_shelf",if:{not:{mem:"clue_license"}}}],lines:["면허증. 긁힌 이름 자리에는…"],choices:[{text:"아무것도 읽을 수 없었다",effects:[{add:{memory:1}}],goto:"s3_q_shelf"},{text:"Mole이라고 적혀 있었다",goto:"s3_q_shelf"},{text:"…기억나지 않는다",goto:"s3_q_shelf"}]},{id:"s3_q_shelf",type:"event",title:"3막 · 기억",dark:!0,onEnter:[{goto:"s3_q_newspaper",if:{not:{mem:"clue_shelf"}}}],lines:["유리 눈알 받침. 마지막 이름표에는…"],choices:[{text:"‘L.’이라고 적혀 있었다",goto:"s3_q_newspaper"},{text:"아무것도 적혀 있지 않았다",effects:[{add:{memory:1}}],goto:"s3_q_newspaper"},{text:"…기억나지 않는다",goto:"s3_q_newspaper"}]},{id:"s3_q_newspaper",type:"event",title:"3막 · 기억",dark:!0,onEnter:[{goto:"s3_q_serum",if:{not:{mem:"clue_newspaper"}}}],lines:["신문 구석의 기사. 실종된 가수의 눈은…"],choices:[{text:"금귤빛이었다",goto:"s3_q_serum"},{text:"잿빛이었다",goto:"s3_q_serum"},{text:"푸른색이었다",effects:[{add:{memory:1}}],goto:"s3_q_serum"}]},{id:"s3_q_serum",type:"event",title:"3막 · 기억",dark:!0,onEnter:[{goto:"s3_q_consent",if:{not:{mem:"clue_serum"}}}],lines:["진액 통 속에서 꿈틀거리던 것은…"],choices:[{text:"구더기",effects:[{add:{memory:1}}],goto:"s3_q_consent"},{text:"쥐",goto:"s3_q_consent"},{text:"나비",goto:"s3_q_consent"}]},{id:"s3_q_consent",type:"event",title:"3막 · 기억",dark:!0,onEnter:[{goto:"s3_q_ceiling",if:{not:{mem:"clue_consent"}}}],lines:["동의서 맨 아래, 아주 작은 글씨는…"],choices:[{text:"‘회복은 빠르다’",goto:"s3_q_ceiling"},{text:"‘시야는 보장하지 않는다’",effects:[{add:{memory:1}}],goto:"s3_q_ceiling"},{text:"…읽지 않았다",goto:"s3_q_ceiling"}]},{id:"s3_q_ceiling",type:"event",title:"3막 · 기억",dark:!0,onEnter:[{goto:"s3_q_specimen",if:{not:{mem:"clue_ceiling"}}}],lines:["진액은 어디서 내려왔더라…"],choices:[{text:"하수도",goto:"s3_q_specimen"},{text:"닥터의 팔",goto:"s3_q_specimen"},{text:"천장 위",effects:[{add:{memory:1}}],goto:"s3_q_specimen"}]},{id:"s3_q_specimen",type:"event",title:"3막 · 기억",dark:!0,onEnter:[{goto:"s3_q_photos",if:{not:{mem:"clue_specimen"}}}],lines:["빈 이름표 앞에 놓여 있던 눈은…"],choices:[{text:"금귤빛",effects:[{add:{memory:1}}],goto:"s3_q_photos"},{text:"푸른빛",goto:"s3_q_photos"},{text:"잿빛",goto:"s3_q_photos"}]},{id:"s3_q_photos",type:"event",title:"3막 · 기억",dark:!0,onEnter:[{goto:"s3_q_telegram",if:{not:{mem:"clue_photos"}}}],lines:["진료의자 아래 함. 사진 묶음의 마지막 장은…"],choices:[{text:"비어 있었다",effects:[{add:{memory:1}}],goto:"s3_q_telegram"},{text:"그녀의 얼굴이었다",goto:"s3_q_telegram"},{text:"…기억나지 않는다",goto:"s3_q_telegram"}]},{id:"s3_q_telegram",type:"event",title:"3막 · 기억",dark:!0,onEnter:[{goto:"s3_q_chart",if:{not:{mem:"hint_telegram"}}}],lines:["핸드백 속 전보. 적혀 있던 사유는…"],choices:[{text:"카메라가 눈을 잡지 못함",effects:[{add:{memory:1}}],goto:"s3_q_chart"},{text:"나이가 너무 많음",goto:"s3_q_chart"},{text:"목소리가 갈라짐",goto:"s3_q_chart"}]},{id:"s3_q_chart",type:"event",title:"3막 · 기억",dark:!0,onEnter:[{goto:"s3_q_vault",if:{not:{mem:"clue_chart"}}}],lines:["의자 위에 떨어져 있던 기록지. 미리 표시되어 있던 칸은…"],choices:[{text:"원래 눈 — 보관",effects:[{add:{memory:1}}],goto:"s3_q_vault"},{text:"원래 눈 — 돌려줌",goto:"s3_q_vault"},{text:"이름 칸, 그녀의 이름",goto:"s3_q_vault"}]},{id:"s3_q_vault",type:"event",title:"3막 · 기억",dark:!0,onEnter:[{goto:"s3_mirror",if:{not:{mem:"clue_vault_jar"}}}],lines:["수장고 맨 끝, 빈 병의 이름표에는…"],choices:[{text:"날짜가 적혀 있었다",effects:[{add:{memory:1}}],goto:"s3_mirror"},{text:"그녀의 이름이 적혀 있었다",goto:"s3_mirror"},{text:"…기억나지 않는다",goto:"s3_mirror"}]},{id:"s3_mirror",type:"event",title:"3막 · 거울",bg:"art/s3_mirror.webp",art:"[S6-4] 붕대를 감고 웃는 여자, 거울",noMirror:!0,lines:["닥터가 거울을 들고 다가온다.",{text:"여자 자신의 손거울이다. 자개 테두리가 손끝에 닿는다.",if:{flag:{mirror_left:!0}}},"여자는 붕대 감긴 눈으로 거울을 더듬더듬 만지다가, 닥터의 손을 잡는다.",{who:"닥터",text:"보이냐?"}],choices:[{text:"(활짝 웃으며) 아름다워!",effects:[{set:{mirror_answer:"beautiful"}}],goto:"s3_exit"},{text:"아무것도 안 보여요.",effects:[{set:{mirror_answer:"nothing"}}],reply:{who:"닥터",text:"…흠. 회복 중이라 그렇지. 아마도."},goto:"s3_exit"},{text:"…이제 상관없어요.",effects:[{set:{mirror_answer:"free"}}],reply:"여자는 거울을 닥터의 손에 도로 쥐여 준다.",goto:"s3_exit"}]},{id:"s3_exit",type:"event",title:"3막 · 출구",bg:"art/s3_exit.webp",art:"[S6-5-1] 벽을 짚으며 나가는 여자",noMirror:!0,lines:[{text:"진리를 깨우친 아르키메데스처럼, 여자는 성공이야! 하고 외치며 몸을 일으킨다.",if:{flag:{mirror_answer:"beautiful"}}},{text:"여자는 천천히 몸을 일으킨다.",if:{not:{flag:{mirror_answer:"beautiful"}}}},"그리고 더듬더듬, 벽을 짚으며 밖으로 나간다."],choices:[{text:"…",goto:"s3_photo"}]},{id:"s3_photo",type:"event",title:"3막 · 출구",bg:"art/s3_photo.webp",art:"[S6-5-2] 문간의 닥터, 복도 끝의 여자",noMirror:!0,lines:[{who:"닥터",text:"어이. 가기 전에 사진이나 한 장 박고 가."}],choices:[{text:"…",if:{lte:{memory:1}},goto:"end_liberation_s"},{text:"…",if:{gte:{memory:2}},goto:"end_truth_s"}]},{id:"end_liberation_s",type:"ending",ending:"liberation",title:"해방",bg:"art/end_liberation.webp",art:"[결말] 눈을 가린 채 웃는 여자와 거울",lines:["여자는 들리지 않는 듯 기쁘게 웃으며, 더듬더듬 지하실 밖으로 떠난다.","닥터는 고개를 갸웃한다. 붕대를 감아서, 아무것도 보이지 않을 텐데.","계단 위 어딘가에서 사진기 셔터 소리가 난다. 여자는 고개를 돌리지 않는다.",{who:"여자",text:"이제야 아무도 날 평가할 수 없네. 나도 포함해서."}]},{id:"end_truth_s",type:"ending",ending:"truth",title:"진실",bg:"art/end_truth_blind.webp",art:"[결말] 벽을 짚고 걷는 여자",lines:["계단 앞에서 여자가 멈춘다.",{who:"여자",text:"긁혀 있던 이름. 비어 있던 이름표. 작은 글씨. 다 기억나요.",if:{not:{mem:"clue_chart"}}},{who:"여자",text:"긁혀 있던 이름. 비어 있던 이름표. 미리 표시돼 있던 칸. 다 기억나요.",if:{mem:"clue_chart"}},{who:"여자",text:"카메라는 거짓말을 안 한다고 했죠. 이제 거짓말할 시선도 없네요."},"여자는 웃으며 빗속으로 걸어 나간다."]},{id:"s3_gold_wake",type:"event",title:"3막 · 황금의 눈",bg:"art/s3_gold_wake.webp",art:"[A컷] 코앞에 닥터의 얼굴",noMirror:!0,lines:[{text:"세상이 눈부시게 하얘졌다가, 천천히 돌아온다.",fx:"flash"},"코앞에 닥터의 얼굴. 처음으로, 아주 선명하게 보인다.",{who:"닥터",text:"보여? 크크. 보이지? 보이지!"}],choices:[{text:"손거울을 찾는다",goto:"s3_gold_mirror"}]},{id:"s3_gold_mirror",type:"event",title:"3막 · 황금의 눈",bg:"art/p1_bag.webp",art:"[S1-2] 손거울",noMirror:!0,lines:["손거울. 금귤빛 홍채. 꿈꾸던 바로 그 눈.","그런데 거울 속 얼굴이 웃고 있다. 여자는 웃지 않았는데.","웃기로 마음먹은 사람의 얼굴로. 닥터처럼."],choices:[{text:"밖으로 나간다",goto:"s3_gold_street"}]},{id:"s3_gold_street",type:"event",title:"3막 · 거리",bg:"art/title.webp",art:"[배경] 비 오는 거리",fx:["rain"],noMirror:!0,lines:["계단을 올라 빗속 거리로 나간다.","지나가는 사람들이 모두 이쪽을 본다. 아무도 깜빡이지 않는다.","반짝이고, 매끈하고, 이름표가 붙어 있을 것만 같은."],choices:[{text:"…",goto:"end_golden_s"}]},{id:"end_golden_s",type:"ending",ending:"golden",title:"황금의 눈",bg:"art/end_golden.webp",art:"[A컷] 유리병 속 눈알들",lines:["여자는 이제 닥터가 보던 세상을 그대로 본다.","모든 눈이 견본이다. 모든 얼굴이 진열장이다.","다음 달, 카메라는 그녀의 눈을 놓치지 않을 것이다.","그녀도 이제 렌즈를 똑바로 본다. 렌즈도, 유리다."]},{id:"s3_removed_wake",type:"event",title:"3막 · 어둠",dark:!0,lines:["어둡다.","얼굴에 손을 대 본다. 붕대 아래, 눈이 있던 자리가… 단추처럼 매끈하다.",{who:"닥터",text:"움직이지 마. 아직 안 끝났어."}],choices:[{text:"…",goto:"s3_removed_doc"}]},{id:"s3_removed_doc",type:"event",title:"3막 · 닥터",bg:"art/end_collection.webp",art:"[배경] 유리 눈알 받침",pov:"doctor",lines:["받침대의 마지막 이름표에 펜을 댄다.","손님 기록지를 꺼낸다. '원래 눈 — 보관.' 처음부터 표시해 둔 칸 옆에, 오늘 날짜를 적는다.","유리병 속에서 무언가가 이쪽을 본다. 아름다운 눈이다.","이제 내 것이다. 크크."],choices:[{text:"…",goto:"end_collection_s"}]},{id:"end_collection_s",type:"ending",ending:"collection",title:"컬렉션",bg:"art/end_collection.webp",art:"[배경] 유리 눈알 받침",lines:["선반에 이름표가 하나 늘었다.","여자의 얼굴은 여전히 재산이다. 다만, 이제 다른 사람의 것이다."]}],$t=[{id:"t2_lab_in",type:"event",title:"2막 · 연구실",bg:"art/end_truth.webp",art:"[A컷] 연구 기록을 뒤지는 닥터",noMirror:!0,lines:["뒷방 문이 열린다. 약품 냄새. 벽마다 종이가 붙어 있다.",{who:"닥터",text:"증명은 말로 하는 게 아니야."},{who:"닥터",text:"읽어."},"닥터는 종이 더미를 한 번 휘젓고는, 문간에 기대어 선다. 나가는 길을 막는 자리다.",{who:"여자",text:"친절하시네요."}],choices:[{text:"…",goto:"t2_lab"}]},{id:"t2_lab",type:"room",title:"2막 · 연구실 · 책상 쪽",bg:"art/t2_lab.webp",art:"[배경] 병이 늘어선 뒷방",idle:"종이와 약품 냄새. 책상 쪽이다. 살펴볼 곳을 누르세요.",hotspots:[{id:"notes",label:"책상 위 기록",rect:[56,58,30,18],text:["날짜와 숫자, 그리고 쥐 그림들.","쥐 칸은 전부 줄이 그어져 있다. 그 아래, 처음으로 사람 칸.","‘1호. 동의함. 결과 —’ 그 뒤는 잉크로 덮여 있다."],textAgain:"‘1호’ 뒤는 여전히 검다.",effects:[{clue:"hint_notes"}]},{id:"blotter",label:"책상의 압지",rect:[30,52,26,16],text:["잉크를 눌러 말리는 압지. 검게 번진 자국이 가득하다.","글씨들이 전부 거꾸로 찍혀 있다."],textAgain:"거꾸로 찍힌 글씨들.",mirror:["거울 속, 압지의 글씨가 바로 선다. 잉크로 덮기 전에 찍힌 것이다.","‘1호. 결과: 실패.’","‘본인 요청으로 이름 삭제.’"],mirrorEffects:[{clue:"hint_blotter"}]},{id:"photo",label:"벽의 액자",rect:[62,24,24,26],if:{not:{seen:"scene:t2_verdict"}},text:["졸업 사진. 하얀 가운의 젊은 남자들이 한 줄로 서 있다.","한 사람의 얼굴만 칼로 긁혀 있다."],goto:"t2_slide"},{id:"photo_after",label:"엎어 놓은 액자",rect:[62,24,24,26],if:{seen:"scene:t2_verdict"},text:"액자는 엎어져 있다. 닥터는 그쪽을 보지 않는다."},{id:"drawer",label:"잠긴 서랍",rect:[52,78,34,18],if:{not:{flag:{first_chart:!0}}},text:"작고 녹슨 열쇠 구멍. 열리지 않는다.",sprite:"obj/drawer.png",use:{item_backkey:{text:["작고 녹슨 열쇠 구멍. 쥐가 물어 온 열쇠가 맞는다.","안에는 진료 기록 한 장. 이름 칸만 찢겨 나가 있다.","‘처치 후 7일. 아무것도 비치지 않는다고 함.’"],effects:[{set:{first_chart:!0}},{add:{suspicion:1}}]}},useHint:"열쇠 구멍이 아주 작다. 녹이 슬어 있다. 어디서 비슷한 걸 봤던가."},{id:"drawer_open",label:"열린 서랍",rect:[52,78,34,18],if:{flag:{first_chart:!0}},text:"찢긴 이름 칸. 그 밖에는 아무것도 없다.",sprite:"obj/drawer.png"},{id:"to_wall",label:"벽 쪽",rect:[88,35,12,30],dir:"right",dirLabel:"벽 쪽 →",goto:"t2_lab_wall"}],ambient:["천장에서 무언가 끌리는 소리.","닥터가 곰방대를 두드린다.","똑.","종이 한 장이 저절로 떨어진다."]},{id:"t2_lab_wall",type:"room",title:"2막 · 연구실 · 벽 쪽",bg:"art/t2_lab.webp",art:"[배경] 병이 늘어선 뒷방",idle:"병들이 늘어선 벽이다. 살펴볼 곳을 누르세요.",hotspots:[{id:"jars",label:"선반의 병들",rect:[14,14,50,32],text:["병마다 흐린 물. 바닥에 하얗게 굳은 것들이 가라앉아 있다.","쌀알 같기도 하고, 무언가가 되다 만 껍질 같기도 하다."],textAgain:"하얀 것들은 움직이지 않는다."},{id:"hatch",label:"천장의 뚜껑",rect:[30,0,44,12],if:{not:{seen:"scene:t2_verdict"}},text:["천장에 네모난 뚜껑. 빗장이 걸려 있다. 틈으로 검은 것이 실처럼 늘어진다.",{who:"닥터",text:"거긴 아직이야."}]},{id:"hatch_open",label:"열린 뚜껑",rect:[30,0,44,12],if:{all:[{seen:"scene:t2_verdict"},{not:{flag:{hatch_open:!0}}}]},text:"뚜껑에 빗장이 걸려 있다. 빗장에는 자물쇠. 사다리는 그 위에 묶여 있다.",use:{item_hatchkey:{text:[{text:"철컥. 빗장이 풀린다. 사다리가 덜컹 내려온다.",fx:"thud"}],effects:[{set:{hatch_open:!0}},{take:"item_hatchkey"}],goto:"t2_hyp"}},useHint:"자물쇠 구멍. 이 방 어딘가에 열쇠가 있을 것이다."},{id:"hatch_go",label:"열린 뚜껑",rect:[30,0,44,12],if:{flag:{hatch_open:!0}},goto:"t2_hyp"},{id:"symbols",label:"벽의 기호표",rect:[14,50,24,16],text:["벽에 붙은 누런 표. 기호마다 숫자가 적혀 있다.","☆ = 1   ▲ = 2   ◆ = 3   ♣ = 5   ● = 7"],effects:[{clue:"hint_symbols"}]},{id:"safe",label:"벽장 금고",rect:[14,70,24,22],if:{not:{has:"item_hatchkey"}},text:"네 자리 숫자 금고. 문틈에 쪽지가 꽂혀 있다.",goto:"t2_safe",effects:[{clue:"hint_safe_note"}]},{id:"to_desk",label:"책상 쪽",rect:[0,35,12,30],dir:"left",dirLabel:"← 책상 쪽",goto:"t2_lab"}],ambient:["천장에서 무언가 끌리는 소리.","닥터가 곰방대를 두드린다.","똑.","종이 한 장이 저절로 떨어진다."]},{id:"t2_slide",type:"puzzle",kind:"slide",title:"2막 · 졸업 사진",bg:"art/t2_lab.webp",art:"[배경] 연구실",noMirror:!0,image:"art/t2_hearing.webp",size:3,shuffle:60,seed:11,hint:"slide",movesPerFail:40,prompt:"액자 유리가 깨져 있다. 사진이 조각나 흩어졌다. 빈칸 옆 조각을 눌러 밀어 맞춘다.",done:"조각이 맞춰진다. 하얀 가운의 젊은 남자. …낯익다.",success:"t2_photo",exit:"t2_lab"},{id:"t2_safe",type:"puzzle",kind:"code",title:"2막 · 금고",bg:"art/t2_lab.webp",art:"[배경] 연구실",noMirror:!0,answer:"7104",hint:"safe",prompt:`쪽지에 적힌 순서.
첫째 ●
둘째 ◆ − ▲
셋째 ♣ × ▲ 의 끝자리
넷째 ☆ + ◆`,wrong:"다이얼이 헛돈다.",success:"t2_safe_open",choices:[],exit:"t2_lab_wall"},{id:"t2_safe_open",type:"event",title:"2막 · 금고",bg:"art/t2_lab.webp",art:"[배경] 연구실",noMirror:!0,onEnter:[{give:"item_hatchkey"}],lines:[{text:"철컥. 금고 문이 열린다.",fx:"thud"},"안에는 녹슨 쇠 열쇠 하나. 손잡이에 ‘위’라고 새겨져 있다.",{who:"닥터",text:"…크크. 계산은 할 줄 아는군."}],choices:[{text:"…",goto:"t2_lab_wall"}]},{id:"t2_photo",type:"event",title:"2막 · 사진",bg:"art/t2_lab.webp",art:"[배경] 병이 늘어선 뒷방",noMirror:!0,lines:["여자가 액자를 집어 든다. 긁힌 얼굴 옆, 가운 주머니에 꽂힌 만년필.","지금 닥터의 가운에 꽂힌 것과 같은 만년필이다.",{who:"여자",text:"이거, 선생님이죠?"},{who:"닥터",text:"……"},{text:"닥터가 사진을 보고 있다. 아니, 사진 너머의 무언가를.",fx:"flash"}],choices:[{text:"…",goto:"t2_h1"}]},{id:"t2_h1",type:"event",pov:"doctor",title:"회상 · 청문회",bg:"art/t2_hearing.webp",art:"[회상] 조명 아래의 젊은 닥터",lines:["하얀 조명 하나. 그 바깥은 전부 어둠이다.","어둠 속에서 목소리들이 종이를 넘긴다. 얼굴은 없다.",{who:"목소리",text:"피고, ▒▒▒ 박사."},"이름이 불리는 순간, 무언가 긁히는 소리가 그 위를 덮는다.",{who:"목소리",text:"첫 번째 손님의 진술서를 읽겠다."},{who:"목소리",text:"‘선생님은 내가 새로 태어날 거라고 했다. 나는 믿었다.’"},{who:"목소리",text:"‘그날 이후로, 아무것도 비치지 않는다.’"},"진술서 맨 아래, 서명 자리는 비어 있다."],choices:[{text:"…",goto:"t2_q1"}]},{id:"t2_q1",type:"event",pov:"doctor",title:"회상 · 청문회",bg:"art/t2_hearing.webp",art:"[회상] 조명 아래의 젊은 닥터",lines:[{who:"목소리",text:"왜 사람에게 했지? 쥐로는 부족했나."}],choices:[{text:"“쥐로는 증명이 안 돼.”",effects:[{add:{m_proof:1}}],reply:"어둠 속에서 펜 긁는 소리.",goto:"t2_q2"},{text:"“…서둘렀어.”",effects:[{add:{m_atone:1}}],reply:"목소리들이 잠시 멈춘다.",goto:"t2_q2"},{text:"(대답하지 않는다)",effects:[{add:{m_obsess:1}}],reply:"젊은 닥터는 조명 바깥의 어둠을 하나씩 세고 있다.",goto:"t2_q2"}]},{id:"t2_q2",type:"event",pov:"doctor",title:"회상 · 청문회",bg:"art/t2_hearing.webp",art:"[회상] 조명 아래의 젊은 닥터",lines:[{who:"목소리",text:"그 손님은 무엇을 원했지?"}],choices:[{text:"“보이기를.”",effects:[{add:{m_atone:1}}],reply:"목소리 하나가 낮게 웃는다.",goto:"t2_q3"},{text:"“아름다워지기를.”",effects:[{add:{m_obsess:1}}],reply:"조명이 아주 조금, 흔들린다.",goto:"t2_q3"},{text:"“…날 믿기를.”",effects:[{add:{m_proof:1}}],reply:"종이 넘기는 소리가 멎는다.",goto:"t2_q3"}]},{id:"t2_q3",type:"event",pov:"doctor",title:"회상 · 청문회",bg:"art/t2_hearing.webp",art:"[회상] 조명 아래의 젊은 닥터",lines:[{who:"목소리",text:"다시 할 건가."}],choices:[{text:"“다음엔 성공해.”",effects:[{add:{m_proof:1}},{set:{motive:"proof"}}],goto:"t2_verdict"},{text:"“……”",effects:[{add:{m_atone:1}},{set:{motive:"atone"}}],goto:"t2_verdict"},{text:"“이미 하고 있어.”",effects:[{add:{m_obsess:1}},{set:{motive:"obsess"}}],goto:"t2_verdict"}]},{id:"t2_verdict",type:"event",pov:"doctor",title:"회상 · 판결",bg:"art/t2_hearing.webp",art:"[회상] 조명 아래의 젊은 닥터",onEnter:[{if:{gte:{m_proof:2}},set:{motive:"proof"}},{if:{gte:{m_atone:2}},set:{motive:"atone"}},{if:{gte:{m_obsess:2}},set:{motive:"obsess"}}],lines:[{who:"목소리",text:"면허를 취소한다."},"종이 한 장이 조명 아래로 미끄러져 온다. 이름이 찍힌 면허증.","젊은 손이 메스를 든다.",{text:"이름 위를, 천천히, 긁는다.",fx:"thud"},{who:"닥터",text:"틀린 건 이름이야. 방법이 아니라.",if:{flag:{motive:"proof"}}},{who:"닥터",text:"…이 이름으로는, 다시 못 봐.",if:{flag:{motive:"atone"}}},{who:"닥터",text:"이름은 필요 없어. 다음 손님만 있으면 돼.",if:{flag:{motive:"obsess"}}}],choices:[{text:"…",goto:"t2_back"}]},{id:"t2_back",type:"event",title:"2막 · 연구실",bg:"art/t2_lab.webp",art:"[배경] 병이 늘어선 뒷방",noMirror:!0,lines:["조명이 꺼진다. 다시, 약품 냄새.",{who:"닥터",text:"…그 사진, 내려놔."},"닥터가 액자를 빼앗아 엎어 놓는다.",{who:"닥터",text:"올라가 봐."},{who:"닥터",text:"증명은 위에 있어."},{who:"닥터",text:"빗장 열쇠? 크크. 그것도 증명해 봐."},"닥터는 문간으로 물러나 곰방대를 문다."],choices:[{text:"…",goto:"t2_lab_wall"}]},{id:"t2_hyp",type:"event",title:"2막 · 두 번째 가설",bg:"art/t2_lab.webp",art:"[배경] 병이 늘어선 뒷방",noMirror:!0,lines:["사다리에 발을 올리기 전, 여자는 노트를 펼친다.","‘진액은 ___ 에서 온다.’"],choices:[{text:"천장 위의 살아 있는 무언가",effects:[{set:{hyp2:!0}}],reply:"천장의 실. 양동이의 꿈틀거림. 병 속의 하얀 껍질. 전부 위를 가리킨다.",goto:"t2_attic"},{text:"이전 손님들의 몸",effects:[{add:{queen:30}}],reply:"…그렇다면 왜 천장에서 떨어질까. 확신 없이 사다리를 오른다.",goto:"t2_attic"},{text:"약품",effects:[{add:{queen:30}}],reply:"약품이라기엔, 너무 꿈틀거렸다. 확신 없이 사다리를 오른다.",goto:"t2_attic"}],exit:"t2_lab_wall"},{id:"t2_attic",type:"room",title:"2막 · 천장 위",bg:"art/t2_attic.webp",art:"[배경] 어둠 속의 마디진 몸",gaze:{var:"queen",label:"기척",look:22,mirror:0},intro:["뚜껑을 밀고 올라선다. 낮은 다락. 숨이 막히게 따뜻하다.","어둠 한가운데, 크고 둥근 것이 숨을 쉰다.","똑바로 보면 안 될 것 같다."],idle:"무언가 숨 쉰다. 똑바로 보지 말 것. 손거울이 있다.",hotspots:[{id:"cover",label:"지붕의 덮개",rect:[4,4,34,24],text:["지붕에 빗물 깔때기. 그 입구를 타르 칠한 덮개가 막고 있다.","덮개 틈으로 가는 빛이 샌다. 새벽이 가깝다."],effects:[{set:{saw_cover:!0}}]},{id:"white",label:"빛 아래의 하얀 것들",rect:[56,64,34,24],text:["빛이 닿는 자리에만, 하얗게 굳은 것들이 흩어져 있다.","껍질 하나가 반쯤 갈라져 있다. 안에서 무언가 나오다 만 것처럼."],effects:[{clue:"hint_white"}]},{id:"tube",label:"바닥으로 늘어진 관",rect:[6,60,34,26],text:["둥근 것에서 관 하나가 바닥 틈으로 이어진다. 그 아래는 진료실 천장이다.","관 끝에서 검은 것이 한 방울, 떨어진다."]},{id:"center",label:"가운데의 둥근 것",rect:[48,12,44,38],text:"고개를 들려는 순간, 그것이 움찔한다.",effects:[{add:{queen:40}}]}],mirror:{text:["손거울을 어깨 너머로 들어 비춘다.","거울 속에서, 그것이 보인다. 부풀어 오른 하얀 몸. 숨 쉴 때마다 마디가 출렁인다.","몸 곳곳에 작고 둥근 것들이 박혀 있다. 젖어서 반짝인다.","그 수십 개가 일제히, 거울 쪽으로 돈다.","여자는 거울을 내린다. 손이 떨리지 않는다. 그게 더 이상하다."],effects:[{set:{saw_queen:!0}},{meta:{know_source:!0}}]},triggers:[{id:"seen",if:{gte:{queen:100}},goto:"t2_attic_seen"}],choices:[{text:"내려간다",if:{flag:{saw_queen:!0}},goto:"t2_deal"}],ambient:["축축한 숨소리.","무언가 마디를 접는 소리.","아래층에서 축음기가 돈다.","…"]},{id:"t2_attic_seen",type:"event",title:"2막 · 천장 위",bg:"art/t2_attic.webp",art:"[배경] 어둠 속의 마디진 몸",noMirror:!0,onEnter:[{set:{saw_queen:!0,looked_direct:!0}},{meta:{know_source:!0}}],lines:["고개를 드는 순간, 어둠 속의 작고 둥근 것들이 일제히 열린다.","수십 개. 전부, 여자 쪽이다.",{text:"뒷걸음질 치던 발이 뚜껑 구멍을 밟는다.",fx:"thud"},{who:"닥터",text:"크크. 똑바로 보면 안 되지."},{who:"닥터",text:"저쪽도 보고 있으니까."}],choices:[{text:"…",goto:"t2_deal"}]},{id:"t2_deal",type:"event",title:"2막 · 거래",bg:"art/a1_peek.webp",art:"[S2-7] 닥터의 눈",noMirror:!0,lines:["다락 아래. 닥터가 사다리를 붙잡고 서 있다.",{who:"닥터",text:"봤지. 여왕님이야."},{who:"닥터",text:"벌레비가 내리던 밤에 떨어지셨어. 내가 주워다 길렀지. 그분이 흘리는 걸로는 뭐든 다시 붙일 수 있어. 뼈든, 살이든, 빛이든. …거의 뭐든."},{who:"닥터",text:"서랍, 열었지. 이름은 내가 찢었어.",if:{flag:{first_chart:!0}}},{who:"닥터",text:"그게 내가 해 줄 수 있는 전부였으니까.",if:{flag:{first_chart:!0}}},{who:"닥터",text:"이제 알겠지. 난 틀리지 않았어. 한 번 서둘렀을 뿐이야. 그러니까 이번엔 네가 증명해. 받든가, 써 주든가.",if:{flag:{motive:"proof"}}},{who:"닥터",text:"그날 이후로 매일 고쳐. 다음 사람은, 다음 사람은 보게 하려고. …누군가는 그걸 봐 줘야 해.",if:{flag:{motive:"atone"}}},{who:"닥터",text:"여왕님은 배가 고파. 새것이 필요해. 아가씨 건 아주, 아주 반짝이고.",if:{flag:{motive:"obsess"}}},{who:"여자",text:"그래서. 저한테 원하는 게 뭔데요."},{who:"닥터",text:"고르라고."},{who:"닥터",text:"아가씨는 고르는 걸 좋아하잖아."}],choices:[{text:"시술을 받는다",goto:"t2_surgery"},{text:"증인이 된다",goto:"end_witness"},{text:"폭로한다",goto:"t2_expose"}]},{id:"t2_surgery",type:"event",title:"2막 · 서명",bg:"art/a1_consent.webp",art:"[S2-8] 동의서와 펜",noMirror:!0,lines:[{who:"여자",text:"받을게요. 대신 이번엔, 작은 글씨까지 다 읽고."},"여자는 동의서를 끝까지 읽는다. 한 줄도 건너뛰지 않는다. 그리고 서명한다.",{who:"닥터",text:"…크크."},"닥터가 웃는다. 이번에는 소리 없이.",{text:"마취 냄새. 위에서, 무언가 숨 쉬는 소리.",fx:"flash"}],choices:[{text:"…",goto:"end_truth_t"}]},{id:"end_truth_t",type:"ending",ending:"truth",title:"진실",bg:"art/end_truth_blind.webp",art:"[결말] 벽을 짚고 걷는 여자",lines:["며칠 뒤, 빗속의 계단.","여자는 벽을 짚고 올라간다. 붕대 아래로는 아무것도 비치지 않는다.",{who:"여자",text:"천장 위의 그것. 긁힌 이름. 비어 있던 서명 자리. 다 알고 받았어요."},{who:"여자",text:"그러니까 이건, 내가 고른 거예요."},"늘 누군가에게 골라지던 얼굴이었다. 이번엔 그녀가 골랐다."]},{id:"end_witness",type:"ending",ending:"witness",title:"증인",bg:"art/end_witness.webp",art:"[결말] 연구 노트에 서명하는 손",lines:["닥터가 연구 노트를 펼쳐 내민다. 첫 장, 비어 있던 서명 자리.",{who:"여자",text:"본 대로만 쓸게요. 꾸미는 건 선생님 몫이고."},"여자가 서명한다. 잉크가 마르기도 전에, 닥터가 노트를 끌어안는다.",{who:"닥터",text:"됐어. 이제 내가 옳았다는 걸 아는 사람이 하나 생겼군.",if:{flag:{motive:"proof"}}},{who:"닥터",text:"…누군가는 봐 줘야 했어.",if:{flag:{motive:"atone"}}},{who:"여자",text:"이번엔 내가 카메라네요.",if:{flag:{motive:"atone"}}},{who:"닥터",text:"증인이 하나. 다음엔 손님이 하나. 크크.",if:{flag:{motive:"obsess"}}},"철문이 열린다. 비는 그쳐 있다.","계단을 오르는 여자의 등 뒤로, 천장 위에서 무언가 숨 쉬는 소리가 따라온다.",{text:"그는 아직 아무에게도 고발당하지 않았다.",if:{not:{ending:"collapse"}}}]},{id:"t2_expose",type:"event",title:"2막 · 폭로",bg:"art/t2_attic.webp",art:"[배경] 어둠 속의 마디진 몸",noMirror:!0,lines:[{who:"여자",text:"증명은 혼자 하세요."},{text:"여자가 다시 사다리를 오른다. 곧장, 아까 본 지붕의 덮개로.",if:{flag:{saw_cover:!0}}},{text:"여자가 다시 사다리를 오른다. 어둠 속, 가는 빛이 새는 곳으로.",if:{not:{flag:{saw_cover:!0}}}},{who:"닥터",text:"안 돼, 안 돼, 그건 아직 증명이 안 끝났어, 빛이 들면 다 굳어 버린다고, 몇 년이야, 몇 년을 하나씩 붙여서 여기까지 왔는데 네가 그걸 한 번에, 한 번에 —",if:{flag:{motive:"proof"}}},{who:"닥터",text:"그만둬, 제발, 그분이 없으면 아무도 못 고쳐, 그날 그 사람도 못 고쳤는데 이번엔, 이번엔 고칠 수 있었는데, 아가씨, 아가씨도 다시 태어나고 싶었잖아 —",if:{flag:{motive:"atone"}}},{who:"닥터",text:"하나, 둘, 셋, 넷, 다섯, 여섯, 일곱, 여덟, 아홉, 열, 열하나, 열둘, 아직 다 못 셌어, 아직 다 못 셌다고, 열셋, 열넷, 열다섯 —",if:{flag:{motive:"obsess"}}},{text:"여자가 덮개를 잡아 뜯는다.",fx:"thud"}],choices:[{text:"…",goto:"t2_light"}]},{id:"t2_light",type:"event",title:"2막 · 빛",bg:"art/t2_light.webp",art:"[S5] 빛 구멍과 나비",noMirror:!0,lines:[{text:"새벽빛이 깔때기를 타고 쏟아진다.",fx:"flash"},"어둠 한가운데의 둥근 것이 빛을 맞는다. 하얀 마디들이 한꺼번에 굳는다.","굳고, 갈라지고, 그 틈에서 무언가 젖은 날개를 편다.","수백 장의 날개가 빛 쪽으로 올라간다. 언젠가 꿈에서 본 것처럼.","둥근 몸이 꺼진다. 박혀 있던 작고 둥근 것들이 바닥으로 굴러 내린다. 수십 개.","하나가 여자의 발끝에서 멈춘다. 흠집 하나 없이, 새것처럼 반짝인다."],choices:[{text:"주워 든다",goto:"t2_pick"}]},{id:"t2_pick",type:"event",title:"2막 · 빗물받이",bg:"art/end_return.webp",art:"[결말] 빗속의 계단",noMirror:!0,fx:["rain"],lines:["사다리 아래, 닥터가 바닥에 주저앉아 위를 올려다보고 있다. 여자를 보지 않는다.","철문을 나선다. 계단 아래 빗물받이.","여자가 손을 편다. 반짝이는 것이 빗물 속으로 떨어진다.",{who:"여자",text:"새것도 금방 낡아."}],choices:[{text:"…",goto:"end_collapse"}]},{id:"end_collapse",type:"ending",ending:"collapse",pov:"doctor",title:"증명 붕괴",bg:"art/end_collapse.webp",art:"[결말] 빛과 날개",lines:["하얀 방. 아무도 없다.","천장에서 더는 아무것도 떨어지지 않는다. 진액 통이 말라 간다.","축음기만 돈다.",{who:"닥터",text:"…증명엔, 언제나 처음이 있는 법이야.",if:{flag:{motive:"proof"}}},{who:"닥터",text:"…이번엔, 아무도 안 다쳤군.",if:{flag:{motive:"atone"}}},{who:"닥터",text:"하나, 둘, 셋, 넷, 다섯, 여섯, 일곱…",if:{flag:{motive:"obsess"}}},{text:"…",if:{flag:{motive:"obsess"}}},{text:"펜은 아직 그의 손에 있었다.",if:{not:{ending:"witness"}}}]}],He="eyeball.run.v1",Ye="eyeball.meta.v1";function rt(e){return{scene:e,vars:{desire:0,suspicion:0,trust:0,coins:3,mirror:0},flags:{},items:[],clues:[],mem:[],seen:{},log:[]}}function Mt(){return{endings:[],runs:0,know:{},eyes:[],seenLines:[]}}function Re(e){try{const t=localStorage.getItem(e);return t?JSON.parse(t):null}catch{return null}}function Fe(e,t){try{localStorage.setItem(e,JSON.stringify(t))}catch{}}const Ze